def add_activity_to_incident(incident_id, activity_type, body, metadata=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_activity_to_incident"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, instance_id=None, credential_id=None, error_code=None):
        # Best-effort request log. No schema provided; use a conventional file if present/created.
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": f"rlog_{uuid.uuid4().hex}",
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": instance_id,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _utcnow(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    if not isinstance(incident_id, str) or not re.match(r"^ginc_[0-9A-Z]{26}$", incident_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "incident_id must be a ginc_ ULID matching ^ginc_[0-9A-Z]{26}$")
    allowed_types = {"comment", "status_change", "link", "note", "update"}
    if not isinstance(activity_type, str) or activity_type not in allowed_types:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"activity_type must be one of {sorted(allowed_types)}")
    if not isinstance(body, str) or body.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body must be a non-empty string")
    if metadata is None:
        metadata = {}
    if not isinstance(metadata, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "metadata must be an object")

    if activity_type in ("comment", "note") and body.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"body is required for activity_type='{activity_type}'")

    incidents = _load("incidents.json")
    incident = next((x for x in incidents if x.get("id") == incident_id), None)
    if not incident:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Incident not found", incident_id=incident_id)

    instance_id = incident.get("instance_id")

    activities = _load("incident_activities.json")

    # Best-effort idempotency by grafana_activity_id if supplied in metadata
    grafana_activity_id = None
    if isinstance(metadata, dict):
        gai = metadata.get("grafana_activity_id")
        if isinstance(gai, str) and gai.strip():
            grafana_activity_id = gai.strip()

    if grafana_activity_id:
        existing = next((a for a in activities if a.get("incident_id") == incident_id and a.get("grafana_activity_id") == grafana_activity_id), None)
        if existing:
            _log("ok", instance_id=instance_id)
            return {"activity": existing}

    # Create queued activity row
    now = _utcnow()
    activity_row = {
        "id": None,  # filled after ULID-ish generation
        "incident_id": incident_id,
        "grafana_activity_id": grafana_activity_id,
        "activity_type": activity_type,
        "body": body,
        "metadata": metadata if metadata is not None else {},
        "posted_by": None,
        "posted_at": None,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # Generate id with required prefix "gia_"? Not specified; use "gia_" and ULID-like 26 chars.
    # We must not raise; generate deterministically enough.
    _alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    import random
    def _ulid26():
        return "".join(random.choice(_alphabet) for _ in range(26))
    activity_row["id"] = f"gia_{_ulid26()}"

    activities.append(activity_row)
    _save("incident_activities.json", activities)

    # Attempt delivery (offline): simulate deterministic success unless metadata requests failure.
    # Business rule: queued -> sent/failed, set posted_at on success; on failure set error_message and status failed.
    fail_reason = None
    if isinstance(metadata, dict):
        sim = metadata.get("simulate")
        if sim == "fail":
            r = metadata.get("error_message")
            fail_reason = r if isinstance(r, str) and r.strip() else "Simulated delivery failure"

    # Reload, mutate the just-created row to ensure persistence correctness
    activities = _load("incident_activities.json")
    idx = next((i for i, a in enumerate(activities) if a.get("id") == activity_row["id"]), None)
    if idx is None:
        _log("error", instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Activity was not persisted")

    if fail_reason:
        activities[idx]["status"] = "failed"
        activities[idx]["error_message"] = fail_reason
        activities[idx]["updated_at"] = _utcnow()
        _save("incident_activities.json", activities)
        _log("ok", instance_id=instance_id)
        return {"activity": activities[idx]}
    else:
        activities[idx]["status"] = "sent"
        activities[idx]["posted_at"] = _utcnow()
        activities[idx]["updated_at"] = _utcnow()
        _save("incident_activities.json", activities)
        _log("ok", instance_id=instance_id)
        return {"activity": activities[idx]}

def create_incident(instance_id, title, severity, room_prefix, status=None, labels=None, is_drill=None, **_extra):
    import json, os, datetime, re, time, uuid, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_incident"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_s, instance_id=None, credential_id=None, error_code=None):
        try:
            logs = _load("request_logs.json")
            logs.append({
                "id": f"rlog_{uuid.uuid4().hex}",
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": instance_id,
                "credential_id": credential_id,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _utcnow(),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(instance_id, str) or not re.match(r"^gfi_[0-9A-Z]{26}$", instance_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a gfi_ ULID matching ^gfi_[0-9A-Z]{26}$")
    if not isinstance(title, str) or title.strip() == "":
        _log("error", instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
    if not isinstance(room_prefix, str) or room_prefix.strip() == "":
        _log("error", instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "room_prefix is required and must be a non-empty string")

    allowed_sev = {"critical", "high", "medium", "low", "info", "sev1", "sev2", "sev3", "sev4", "sev5"}
    if not isinstance(severity, str) or severity not in allowed_sev:
        _log("error", instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"severity must be one of {sorted(allowed_sev)}")

    allowed_status = {"active", "resolved", "cancelled"}
    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"status must be one of {sorted(allowed_status)}")

    if labels is None:
        labels = {}
    if not isinstance(labels, dict):
        _log("error", instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "labels must be an object")

    if is_drill is None:
        is_drill = False
    if not isinstance(is_drill, bool):
        _log("error", instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_drill must be a boolean")

    instances = _load("grafana_instances.json")
    inst = next((x for x in instances if x.get("id") == instance_id), None)
    if not inst:
        _log("error", instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance connector not found", instance_id=instance_id)
    if inst.get("status") != "active":
        _log("error", instance_id=instance_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance connector is disabled", instance_id=instance_id)

    incidents = _load("incidents.json")

    # Idempotency: best-effort via client-supplied external id in labels, if present.
    existing = None
    ext_id = labels.get("grafana_incident_id") if isinstance(labels, dict) else None
    if isinstance(ext_id, str) and ext_id.strip():
        ext_id = ext_id.strip()
        existing = next((i for i in incidents if i.get("instance_id") == instance_id and i.get("grafana_incident_id") == ext_id), None)
        if existing:
            # Update mutable fields to match request (idempotent upsert semantics)
            now = _utcnow()
            existing["title"] = title
            existing["severity"] = severity
            existing["room_prefix"] = room_prefix
            existing["labels"] = labels
            existing["is_drill"] = is_drill
            # status transition rules
            transitions = {"active": {"resolved", "cancelled"}, "resolved": {"active"}, "cancelled": set()}
            cur = existing.get("status")
            if status != cur:
                if cur not in transitions or status not in transitions[cur]:
                    _log("error", instance_id=instance_id, error_code="INVALID_TRANSITION")
                    return _err("INVALID_TRANSITION", f"Illegal incident status transition {cur} -> {status}")
                existing["status"] = status
                if status == "resolved":
                    existing["resolved_at"] = existing.get("resolved_at") or now
                else:
                    existing["resolved_at"] = None
            existing["updated_at"] = now
            _save("incidents.json", incidents)
            _log("ok", instance_id=instance_id)
            return {"incident": existing}

    # Generate external grafana_incident_id if not provided
    if not ext_id:
        ext_id = str(uuid.uuid4())

    # Enforce unique(instance_id, grafana_incident_id)
    if next((i for i in incidents if i.get("instance_id") == instance_id and i.get("grafana_incident_id") == ext_id), None):
        _log("error", instance_id=instance_id, error_code="CONFLICT")
        return _err("CONFLICT", "Incident with this grafana_incident_id already exists", instance_id=instance_id, grafana_incident_id=ext_id)

    _alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid26():
        return "".join(random.choice(_alphabet) for _ in range(26))

    now = _utcnow()
    row = {
        "id": f"ginc_{_ulid26()}",
        "instance_id": instance_id,
        "grafana_incident_id": ext_id,
        "title": title,
        "severity": severity,
        "status": status,
        "room_prefix": room_prefix,
        "labels": labels,
        "is_drill": is_drill,
        "grafana_url": None,
        "opened_at": now if status == "active" else None,
        "resolved_at": now if status == "resolved" else None,
        "created_by": None,
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }
    if status != "resolved":
        row["resolved_at"] = None

    incidents.append(row)
    _save("incidents.json", incidents)
    _log("ok", instance_id=instance_id)
    return {"incident": row}

def find_error_pattern_logs(instance_id, datasource_uid, query_text, time_start, time_end, limit=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "find_error_pattern_logs"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _result_size_and_truncate(obj, limit_bytes=1024 * 1024):
        try:
            raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        except Exception:
            return {"truncated": True, "reason": "non_serializable"}
        if len(raw) <= limit_bytes:
            return obj
        # summarize deterministically
        if isinstance(obj, dict):
            out = {"truncated": True, "original_bytes": len(raw)}
            # keep a few known keys if present
            for k in ("patterns", "summary", "items", "warnings", "meta"):
                if k in obj:
                    out[k] = obj[k]
            # ensure we don't still exceed drastically
            try:
                raw2 = json.dumps(out, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
                if len(raw2) <= limit_bytes:
                    return out
            except Exception:
                pass
            return {"truncated": True, "original_bytes": len(raw), "summary": "payload too large"}
        if isinstance(obj, list):
            kept = []
            size = 0
            for it in obj:
                piece = json.dumps(it, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
                if size + len(piece) > int(limit_bytes * 0.9):
                    break
                kept.append(it)
                size += len(piece)
            return {"truncated": True, "original_bytes": len(raw), "items": kept}
        return {"truncated": True, "original_bytes": len(raw), "summary": str(type(obj))}

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        # Always attempt to record, but never fail the call because logging failed.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("rlog_"),
            "service": "grafana_server",
            "endpoint": endpoint,
            "instance_id": used_instance_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # ---- validation ----
    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-Z]{26}$", instance_id) is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a gfi_ ULID", field="instance_id")
    if not isinstance(datasource_uid, str) or not datasource_uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "datasource_uid must be a non-empty string", field="datasource_uid")
    if not isinstance(query_text, str) or not query_text.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query_text must be a non-empty string", field="query_text")

    ts = _parse_dt(time_start)
    te = _parse_dt(time_end)
    if ts is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_start must be an ISO-8601 datetime", field="time_start")
    if te is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_end must be an ISO-8601 datetime", field="time_end")
    if te <= ts:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_end must be after time_start", field="time_end")

    if limit is None:
        limit = 200
    try:
        limit = int(limit)
    except Exception:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be >= 1", field="limit")
    if limit > 5000:
        limit = 5000

    # ---- resolve instance (must exist & preferably active) ----
    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)
    if inst.get("status") != "active":
        _append_request_log("error", used_instance_id=instance_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance is disabled", instance_id=instance_id)

    # ---- resolve datasource: DO NOT error if caller provided a Tempo uid; pick a workable Loki datasource ----
    resources = _load("grafana_resources.json")
    if not isinstance(resources, list):
        resources = []
    # Try to find the requested uid as a datasource (any type)
    req_ds = None
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("uid") == datasource_uid and r.get("status") == "active":
            req_ds = r
            break

    chosen_ds = None
    resolution_note = None
    # If the requested datasource is Loki, use it; otherwise fall back to any active Loki datasource for this instance
    if req_ds and req_ds.get("type") == "loki":
        chosen_ds = req_ds
    else:
        lokis = [r for r in resources if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("status") == "active" and r.get("type") == "loki" and isinstance(r.get("uid"), str) and r.get("uid")]
        lokis.sort(key=lambda x: (0 if x.get("is_default") else 1, x.get("name") or "", x.get("uid") or ""))
        if lokis:
            chosen_ds = lokis[0]
            if req_ds is None:
                resolution_note = "requested datasource_uid not found; used default Loki datasource"
            else:
                resolution_note = f"requested datasource_uid is not Loki (type={req_ds.get('type')}); used Loki datasource instead"
        else:
            _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND", meta={"datasource_uid": datasource_uid})
            return _err("NOT_FOUND", "No active Loki datasource available for this instance", instance_id=instance_id, datasource_uid=datasource_uid)

    # ---- create async job and block/poll until finished ----
    jobs = _load("observability_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    now_iso = _now_iso()
    job_id = _new_id("goj_")
    job = {
        "id": job_id,
        "instance_id": instance_id,
        "job_type": "loki_find_error_pattern_logs",
        "datasource_uid": chosen_ds.get("uid"),
        "datasource_type": "loki",
        "query_text": query_text,
        "label_name": None,
        "series_selectors": [],
        "regex_filter": None,
        "time_start": ts.isoformat(),
        "time_end": te.isoformat(),
        "step_seconds": None,
        "limit": limit,
        "direction": "backward",
        "page_cursor": None,
        "page_limit": None,
        "sift_investigation_uuid": None,
        "sift_analysis_uuid": None,
        "assertion_entity": None,
        "result": None,
        "status": "queued",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_by": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("observability_jobs.json", jobs)

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("observability_jobs.json", jobs)

    # "Execute" analysis locally (offline): produce deterministic-ish pattern summary based on query_text
    try:
        q = query_text.strip()
        # crude heuristic: find common error-ish tokens; create patterns list
        tokens = re.findall(r"[A-Za-z0-9_.:-]{3,}", q.lower())
        candidates = [t for t in tokens if any(x in t for x in ("error", "exception", "fail", "panic", "timeout", "5", "4"))]
        # unique while preserving order
        seen = set()
        uniq = []
        for t in candidates:
            if t not in seen:
                uniq.append(t)
                seen.add(t)
        # build patterns (up to limit)
        patterns = []
        base = max(1, len(tokens))
        for i, t in enumerate(uniq[: max(1, min(limit, 50))]):
            # create stable "elevation" score
            h = int(hashlib.sha256((t + "|" + instance_id).encode("utf-8")).hexdigest()[:8], 16)
            elevation = round(1.0 + (h % 500) / 100.0, 2)  # 1.00 - 6.00
            patterns.append({
                "pattern": t,
                "elevation": elevation,
                "sample_query": query_text,
                "sample_count": int((h % 200) + 1),
                "baseline_count": int(((h // 3) % 200) + 1),
            })
        if not patterns:
            patterns = []
        result_obj = {
            "datasource_uid": chosen_ds.get("uid"),
            "datasource_type": "loki",
            "requested_datasource_uid": datasource_uid,
            "resolution_note": resolution_note,
            "time_start": ts.isoformat(),
            "time_end": te.isoformat(),
            "limit": limit,
            "patterns": patterns[:limit],
            "summary": {
                "num_patterns": len(patterns[:limit]),
                "query_tokens": base,
            },
        }
