def find_slow_requests(instance_id, datasource_uid, time_start, time_end, limit=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "find_slow_requests"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _result_size_and_truncate(obj, limit_bytes=1024 * 1024):
        try:
            raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        except Exception:
            return {"truncated": True, "reason": "non_serializable"}
        if len(raw) <= limit_bytes:
            return obj
        if isinstance(obj, list):
            kept = []
            size = 0
            for it in obj:
                piece = json.dumps(it, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
                if size + len(piece) > int(limit_bytes * 0.9):
                    break
                kept.append(it)
                size += len(piece)
            return {"truncated": True, "original_bytes": len(raw), "items": kept}
        return {"truncated": True, "original_bytes": len(raw), "summary": "payload too large"}

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("rlog_"),
            "service": "grafana_server",
            "endpoint": endpoint,
            "instance_id": used_instance_id,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-Z]{26}$", instance_id) is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a gfi_ ULID", field="instance_id")
    if not isinstance(datasource_uid, str) or not datasource_uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "datasource_uid must be a non-empty string", field="datasource_uid")

    ts = _parse_dt(time_start)
    te = _parse_dt(time_end)
    if ts is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_start must be an ISO-8601 datetime", field="time_start")
    if te is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_end must be an ISO-8601 datetime", field="time_end")
    if te <= ts:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "time_end must be after time_start", field="time_end")

    if limit is None:
        limit = 100
    try:
        limit = int(limit)
    except Exception:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be >= 1", field="limit")
    if limit > 5000:
        limit = 5000

    # Resolve instance
    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)
    if inst.get("status") != "active":
        _append_request_log("error", used_instance_id=instance_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance is disabled", instance_id=instance_id)

    # Resolve tempo datasource; if requested uid isn't tempo, fall back to a tempo datasource for this instance.
    resources = _load("grafana_resources.json")
    if not isinstance(resources, list):
        resources = []
    req_ds = next((r for r in resources if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("uid") == datasource_uid and r.get("status") == "active"), None)

    chosen_ds = None
    resolution_note = None
    if req_ds and req_ds.get("type") == "tempo":
        chosen_ds = req_ds
    else:
        tempos = [r for r in resources if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("status") == "active" and r.get("type") == "tempo" and isinstance(r.get("uid"), str) and r.get("uid")]
        tempos.sort(key=lambda x: (0 if x.get("is_default") else 1, x.get("name") or "", x.get("uid") or ""))
        if tempos:
            chosen_ds = tempos[0]
            if req_ds is None:
                resolution_note = "requested datasource_uid not found; used default Tempo datasource"
            else:
                resolution_note = f"requested datasource_uid is not Tempo (type={req_ds.get('type')}); used Tempo datasource instead"
        else:
            _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND", meta={"datasource_uid": datasource_uid})
            return _err("NOT_FOUND", "No active Tempo datasource available for this instance", instance_id=instance_id, datasource_uid=datasource_uid)

    # Create async job and block until finished
    jobs = _load("observability_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    now_iso = _now_iso()
    job_id = _new_id("goj_")
    job = {
        "id": job_id,
        "instance_id": instance_id,
        "job_type": "tempo_find_slow_requests",
        "datasource_uid": chosen_ds.get("uid"),
        "datasource_type": "tempo",
        "query_text": None,
        "label_name": None,
        "series_selectors": [],
        "regex_filter": None,
        "time_start": ts.isoformat(),
        "time_end": te.isoformat(),
        "step_seconds": None,
        "limit": limit,
        "direction": None,
        "page_cursor": None,
        "page_limit": None,
        "sift_investigation_uuid": None,
        "sift_analysis_uuid": None,
        "assertion_entity": None,
        "result": None,
        "status": "queued",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_by": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("observability_jobs.json", jobs)

    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("observability_jobs.json", jobs)

    # Offline analysis: synthesize "slow spans" list
    try:
        # derive a deterministic-ish set of candidates from inputs
        seed = hashlib.sha256((instance_id + "|" + chosen_ds.get("uid", "") + "|" + ts.isoformat() + "|" + te.isoformat()).encode("utf-8")).hexdigest()
        n_items = min(limit, 50)
        items = []
        for i in range(n_items):
            h = hashlib.sha256((seed + "|" + str(i)).encode("utf-8")).hexdigest()
            dur_ms = 500 + (int(h[:6], 16) % 250000)  # 0.5s - 250.5s
            trace_id = h[6:38]
            span_id = h[38:54]
            items.append({
                "trace_id": trace_id,
                "span_id": span_id,
                "service": "unknown",
                "operation": "request",
                "duration_ms": dur_ms,
                "start_time": ts.isoformat(),
                "end_time": te.isoformat(),
            })
        items.sort(key=lambda x: x.get("duration_ms", 0), reverse=True)
        result_obj = {
            "datasource_uid": chosen_ds.get("uid"),
            "datasource_type": "tempo",
            "requested_datasource_uid": datasource_uid,
            "resolution_note": resolution_note,
            "time_start": ts.isoformat(),
            "time_end": te.isoformat(),
            "limit": limit,
            "items": items[:limit],
            "summary": {"count": len(items[:limit]), "max_duration_ms": items[0]["duration_ms"] if items else None},
        }
        job["result"] = _result_size_and_truncate(result_obj)
        job["status"] = "succeeded"
        job["error_message"] = None
    except Exception as e:
        job["status"] = "failed"
        job["error_message"] = str(e)[:5000]
        job["result"] = _result_size_and_truncate({"truncated": False, "error": job["error_message"]})

    job["finished_at"] = _now_iso()
    job["updated_at"] = job["finished_at"]
    _save("observability_jobs.json", jobs)

    if job["status"] != "succeeded":
        _append_request_log("error", used_instance_id=instance_id, error_code="CONFLICT", meta={"job_id": job_id})
        return _err("CONFLICT", "Job failed", job_id=job_id, error_message=job.get("error_message"))

    _append_request_log("ok", used_instance_id=instance_id, error_code=None, meta={"job_id": job_id})
    return {"job": job, "result": job.get("result")}

def get_alert_rule_by_uid(instance_id, uid, **_extra):
