            "time_end": te.isoformat().replace("+00:00", "Z"),
            "summary": existing.get("result"),
            "job_id": existing.get("id"),
        }

    job = {
        "id": _new_job_id(),
        "instance_id": instance_id,
        "job_type": "assertions_get",
        "datasource_uid": None,
        "datasource_type": None,
        "query_text": None,
        "label_name": None,
        "series_selectors": [],
        "regex_filter": None,
        "time_start": ts.isoformat().replace("+00:00", "Z"),
        "time_end": te.isoformat().replace("+00:00", "Z"),
        "step_seconds": None,
        "limit": None,
        "direction": None,
        "page_cursor": None,
        "page_limit": None,
        "sift_investigation_uuid": None,
        "sift_analysis_uuid": None,
        "assertion_entity": assertion_entity,
        "result": None,
        "status": "running",
        "error_message": None,
        "started_at": now_iso,
        "finished_at": None,
        "created_by": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("observability_jobs.json", jobs)

    # Offline deterministic "assertion summary": summarize incident activity density as a proxy signal.
    incidents = _load("incidents.json")
    if not isinstance(incidents, list):
        incidents = []
    activities = _load("incident_activities.json")
    if not isinstance(activities, list):
        activities = []

    # Filter to window using created_at/posted_at; prefer posted_at.
    def _dt_of(r):
        for k in ("posted_at", "created_at", "opened_at", "updated_at"):
            v = r.get(k)
            d = _parse_dt(v) if isinstance(v, str) else None
            if d is not None:
                return d
        return None

    incident_ids = {r.get("id") for r in incidents if isinstance(r, dict) and r.get("instance_id") == instance_id}
    act_in_window = 0
    failed = 0
    for a in activities:
        if not isinstance(a, dict):
            continue
        if a.get("incident_id") not in incident_ids:
            continue
        d = _dt_of(a)
        if d is None or d < ts or d > te:
            continue
        act_in_window += 1
        if a.get("status") == "failed":
            failed += 1

    duration_s = max(1.0, (te - ts).total_seconds())
    rate_per_hour = (act_in_window / duration_s) * 3600.0

    entity_key = "|".join(
        str(assertion_entity.get(k, "") or "") for k in ("type", "name", "env", "site", "namespace")
    ).strip("|")
    if not entity_key:
        entity_key = "unspecified"

    summary = {
        "fingerprint": fp,
        "entity": {"key": entity_key, **assertion_entity},
        "window": {"start": job["time_start"], "end": job["time_end"], "duration_seconds": int(duration_s)},
        "signals": {
            "activity_events": act_in_window,
            "failed_activity_events": failed,
            "activity_rate_per_hour": float(f"{rate_per_hour:.6f}"),
        },
        "status": "ok",
        "truncated": False,
    }
    summary, truncated = _truncate_result(summary)
    if isinstance(summary, dict) and truncated:
        summary["truncated"] = True

    # Complete job
    job["status"] = "succeeded"
    job["result"] = summary
    job["finished_at"] = _now_iso()
    job["updated_at"] = job["finished_at"]
    _save("observability_jobs.json", jobs)

    _append_request_log("ok", used_instance_id=instance_id, meta={"job_id": job["id"], "cache": "miss"})
    return {
        "instance_id": instance_id,
        "assertion_entity": assertion_entity,
        "time_start": job["time_start"],
        "time_end": job["time_end"],
        "summary": summary,
        "job_id": job["id"],
    }

def get_current_oncall_users(instance_id, schedule_id, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid_ok(v):
        return isinstance(v, str) and re.match(r"^gfi_[0-9A-Z]{26}$", v) is not None

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(8).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _ensure_request_log_row(endpoint, inst_id, status_code, latency_ms, error_code=None):
        for fname in ("request_logs.json", "api_requests.json", "audit_log.json", "usage_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                row = {
                    "id": _new_id("rql_"),
                    "endpoint": endpoint,
                    "instance_id": inst_id,
                    "status": status_code,
                    "error_code": error_code,
                    "latency_ms": latency_ms,
                    "timestamp": _now_iso(),
                }
                if isinstance(logs, list):
                    logs.append(row)
                    _save(fname, logs)
                break

    t0 = time.time()

    if not _ulid_ok(instance_id):
        latency = int((time.time() - t0) * 1000)
        _ensure_request_log_row("get_current_oncall_users", instance_id, 400, latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a gfi_ ULID")
    if not isinstance(schedule_id, int):
        latency = int((time.time() - t0) * 1000)
        _ensure_request_log_row("get_current_oncall_users", instance_id, 400, latency, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schedule_id must be an integer")

    instances = _load("grafana_instances.json")
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        latency = int((time.time() - t0) * 1000)
        _ensure_request_log_row("get_current_oncall_users", instance_id, 404, latency, "NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance connector not found", instance_id=instance_id)
    if inst.get("status") != "active":
        latency = int((time.time() - t0) * 1000)
        _ensure_request_log_row("get_current_oncall_users", instance_id, 401, latency, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance connector is disabled", instance_id=instance_id)

    directory = _load("oncall_directory.json")

    # TTL refresh requirement: if older than configured TTL, refresh before responding.
    # Offline: "refresh" is modeled as setting last_synced_at to now and transitioning stale->active.
    TTL_SECONDS = 300
    now = _now()

    schedule = next(
        (r for r in directory
         if r.get("instance_id") == instance_id and r.get("entity_type") == "schedule" and r.get("oncall_id") == schedule_id),
        None
    )
    if not schedule or schedule.get("status") == "deleted":
        latency = int((time.time() - t0) * 1000)
        _ensure_request_log_row("get_current_oncall_users", instance_id, 404, latency, "NOT_FOUND")
        return _err("NOT_FOUND", "OnCall schedule not found", instance_id=instance_id, schedule_id=schedule_id)

    changed = False
    last_synced = _parse_dt(schedule.get("last_synced_at"))
    if schedule.get("status") == "stale" or last_synced is None or (now - last_synced.astimezone(datetime.timezone.utc)).total_seconds() > TTL_SECONDS:
        # Refresh modeled locally
        if schedule.get("status") == "stale":
            schedule["status"] = "active"
        schedule["last_synced_at"] = now.isoformat()
        schedule["updated_at"] = now.isoformat()
        changed = True

    # Determine current oncall users:
    # - find shifts for this schedule where now is in [shift_start, shift_end)
    shifts = []
    for r in directory:
        if r.get("instance_id") != instance_id or r.get("entity_type") != "shift" or r.get("status") == "deleted":
            continue
        if r.get("schedule_id") != schedule_id:
            continue
        ss = _parse_dt(r.get("shift_start"))
        se = _parse_dt(r.get("shift_end"))
        if ss is None or se is None:
            continue
        ss = ss.astimezone(datetime.timezone.utc)
        se = se.astimezone(datetime.timezone.utc)
        if ss <= now < se:
            shifts.append(r)

    # Heuristic mapping from shift -> users:
    # if shift.details contains "user_ids" list, use it; else fall back to users with matching schedule_id (not modeled),
    # else return empty.
    users = []
    user_ids = set()
    for sh in shifts:
        det = sh.get("details") if isinstance(sh.get("details"), dict) else {}
        uids = det.get("user_ids")
        if isinstance(uids, list):
            for x in uids:
                if isinstance(x, int):
                    user_ids.add(x)

    if user_ids:
        for r in directory:
            if r.get("instance_id") != instance_id or r.get("entity_type") != "user" or r.get("status") == "deleted":
                continue
            if r.get("oncall_id") in user_ids:
                users.append({
                    "id": r.get("oncall_id"),
                    "username": r.get("username"),
                    "name": r.get("name"),
                    "team_id": r.get("team_id"),
                    "details": r.get("details"),
                })

    # Persist refresh changes
    if changed:
        _save("oncall_directory.json", directory)

    latency = int((time.time() - t0) * 1000)
    _ensure_request_log_row("get_current_oncall_users", instance_id, 200, latency, None)

    return {
        "schedule": {"id": schedule.get("oncall_id"), "name": schedule.get("name")},
        "as_of": now.isoformat(),
        "users": users,
    }

def get_dashboard_by_uid(instance_id, uid, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_dashboard_by_uid"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_utc().isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("rlog_"),
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": used_instance_id,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-Z]{26}$", instance_id or "") is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a gfi_ ULID", field="instance_id")
    if not isinstance(uid, str) or not uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "uid must be a non-empty string", field="uid")
    uid = uid.strip()

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    resources = _load("grafana_resources.json")
    if not isinstance(resources, list):
        resources = []

    row = next(
        (
            r
            for r in resources
            if isinstance(r, dict)
            and r.get("instance_id") == instance_id
            and r.get("resource_type") == "dashboard"
            and r.get("uid") == uid
        ),
        None,
    )

    if row is None:
        # Per contract: reads with no matches return empty result set style (not error).
        _append_request_log("ok", used_instance_id=instance_id, meta={"uid": uid, "cache": "miss"})
        return {"instance_id": instance_id, "uid": uid, "dashboard": None, "cache": {"hit": False}}

    # Refresh if stale or missing spec
    mutated = False
    now_iso = _now_iso()

    if row.get("status") in ("deleted",):
        _append_request_log("ok", used_instance_id=instance_id, meta={"uid": uid, "cache": "deleted"})
        return {"instance_id": instance_id, "uid": uid, "dashboard": None, "cache": {"hit": False, "reason": "deleted"}}

    if row.get("status") == "stale":
        row["status"] = "active"
        mutated = True

    if row.get("spec") is None:
        # Minimal offline spec
        row["spec"] = {
            "uid": row.get("uid"),
            "title": row.get("title"),
            "tags": row.get("tags") if isinstance(row.get("tags"), list) else [],
            "panels": [],
            "templating": {"list": []},
            "time": {},
            "timezone": "browser",
        }
        mutated = True

    if not row.get("spec_etag"):
        row["spec_etag"] = "local:" + hashlib.sha256(
            json.dumps(row.get("spec"), ensure_ascii=False, sort_keys=True).encode("utf-8")
        ).hexdigest()[:16]
        mutated = True

    row["last_synced_at"] = now_iso
    row["updated_at"] = now_iso
    if mutated:
        _save("grafana_resources.json", resources)

    _append_request_log("ok", used_instance_id=instance_id, meta={"uid": uid, "cache": "hit"})
    return {
        "instance_id": instance_id,
        "uid": uid,
        "dashboard": {
            "id": row.get("id"),
            "uid": row.get("uid"),
            "title": row.get("title"),
            "folder_uid": row.get("folder_uid"),
            "folder_title": row.get("folder_title"),
            "url": row.get("url"),
            "tags": row.get("tags") if isinstance(row.get("tags"), list) else [],
            "spec_etag": row.get("spec_etag"),
            "spec": row.get("spec"),
            "last_synced_at": row.get("last_synced_at"),
        },
        "cache": {"hit": True},
    }

