                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id or "") is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a valid gfi_ ULID.", field="instance_id")
    if not isinstance(dashboard_uid, str) or not dashboard_uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "dashboard_uid must be a non-empty string.", field="dashboard_uid")
    dashboard_uid = dashboard_uid.strip()

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    resources = _load("grafana_resources.json")
    if not isinstance(resources, list):
        resources = []

    dash = next(
        (
            r
            for r in resources
            if isinstance(r, dict)
            and r.get("instance_id") == instance_id
            and r.get("resource_type") == "dashboard"
            and r.get("uid") == dashboard_uid
            and r.get("status") != "deleted"
        ),
        None,
    )

    if dash is None:
        _append_request_log("ok", used_instance_id=instance_id, meta={"dashboard_uid": dashboard_uid, "cache": "miss"})
        return {"instance_id": instance_id, "dashboard_uid": dashboard_uid, "panels": [], "dashboard": None}

    spec = dash.get("spec")
    if not isinstance(spec, dict):
        spec = {}

    panels = spec.get("panels")
    if not isinstance(panels, list):
        panels = []

    # Extract panel targets recursively (rows can include nested panels)
    out = []

    def _norm_ds(ds):
        if isinstance(ds, str):
            return {"uid": ds, "type": None}
        if isinstance(ds, dict):
            return {"uid": ds.get("uid") or ds.get("name"), "type": ds.get("type")}
        return {"uid": None, "type": None}

    def _extract_from_panel(p):
        if not isinstance(p, dict):
            return
        title = p.get("title")
        pid = p.get("id")
        ds = _norm_ds(p.get("datasource"))
        targets = p.get("targets")
        if not isinstance(targets, list):
            targets = []
        # Grafana panels can also store queries under "query" or "transformations"; we include "targets" only.
        if title is not None or targets:
            out.append(
                {
                    "panel_id": pid,
                    "panel_title": title,
                    "datasource": ds,
                    "targets": targets,
                }
            )
        nested = p.get("panels")
        if isinstance(nested, list):
            for ch in nested:
                _extract_from_panel(ch)

    for p in panels:
        _extract_from_panel(p)

    _append_request_log("ok", used_instance_id=instance_id, meta={"dashboard_uid": dashboard_uid, "panels": len(out)})
    return {
        "instance_id": instance_id,
        "dashboard_uid": dashboard_uid,
        "dashboard": {"uid": dash.get("uid"), "title": dash.get("title"), "url": dash.get("url")},
        "panels": out,
    }

