        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    name = name.strip()

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    resources = _load("grafana_resources.json")
    if not isinstance(resources, list):
        resources = []

    matches = [
        r
        for r in resources
        if isinstance(r, dict)
        and r.get("instance_id") == instance_id
        and r.get("resource_type") == "datasource"
        and r.get("status") == "active"
        and r.get("name") == name
    ]

    if len(matches) == 0:
        _append_request_log("ok", used_instance_id=instance_id, meta={"name": name, "cache": "miss"})
        return {"instance_id": instance_id, "name": name, "datasource": None, "cache": {"hit": False}}

    if len(matches) > 1:
        # Ambiguity must be deterministic error
        matches_sorted = sorted(matches, key=lambda r: (str(r.get("uid") or ""), str(r.get("id") or "")))
        _append_request_log("error", used_instance_id=instance_id, error_code="CONFLICT", meta={"name": name})
        return _err(
            "CONFLICT",
            "Multiple datasources match this exact name",
            instance_id=instance_id,
            name=name,
            matches=[{"id": r.get("id"), "uid": r.get("uid"), "type": r.get("type")} for r in matches_sorted[:10]],
        )

    ds = matches[0]
    _append_request_log("ok", used_instance_id=instance_id, meta={"name": name, "cache": "hit"})
    return {
        "instance_id": instance_id,
        "name": name,
        "datasource": {
            "id": ds.get("id"),
            "uid": ds.get("uid"),
            "numeric_id": ds.get("numeric_id"),
