def get_incident(incident_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    req_id = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(endpoint, status_code, message=None):
        nonlocal req_id
        logs = _load("request_logs.json")
        req_id = f"req_{int(time.time()*1000)}_{len(logs)+1}"
        logs.append(
            {
                "id": req_id,
                "endpoint": endpoint,
                "status": status_code,
                "message": message,
                "timestamp": _now(),
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(incident_id, str) or not re.match(r"^ginc_[0-9A-HJKMNP-TV-Z]{26}$", incident_id):
        _log_request("get_incident", "VALIDATION_ERROR", "incident_id must be a ginc_ ULID")
        return _err("VALIDATION_ERROR", "incident_id must be a ginc_ ULID")

    incidents = _load("incidents.json")
    inc = next((r for r in incidents if r.get("id") == incident_id), None)
    if not inc:
        _log_request("get_incident", "NOT_FOUND", "Incident not found")
        return _err("NOT_FOUND", "Incident not found")

    # Ensure instance exists and active (permission proxy)
    instances = _load("grafana_instances.json")
    inst = next((r for r in instances if r.get("id") == inc.get("instance_id")), None)
    if not inst:
        _log_request("get_incident", "UNAUTHORIZED", "Owning Grafana instance not available")
        return _err("UNAUTHORIZED", "Owning Grafana instance not available")
    if inst.get("status") != "active":
        _log_request("get_incident", "UNAUTHORIZED", "Owning Grafana instance is disabled")
        return _err("UNAUTHORIZED", "Owning Grafana instance is disabled")

    # Validate resolved_at rule on read (data integrity)
    if inc.get("status") != "resolved" and inc.get("resolved_at") is not None:
        # Don't mutate silently; just surface a validation error
        _log_request("get_incident", "VALIDATION_ERROR", "resolved_at must be null unless status='resolved'")
        return _err("VALIDATION_ERROR", "resolved_at must be null unless status='resolved'")

    # Attach activities (best-effort)
    activities = _load("incident_activities.json")
    inc_acts = [a for a in activities if a.get("incident_id") == incident_id]

    _log_request("get_incident", "success")
    return {
        "incident": inc,
        "activities": sorted(inc_acts, key=lambda a: (a.get("posted_at") or a.get("created_at") or "")),
        "meta": {"activity_count": len(inc_acts), "instance_id": inc.get("instance_id")},
    }

