    def _now_iso():
        return _now_utc().isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("rlog_"),
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": used_instance_id,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id or "") is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a valid gfi_ ULID.", field="instance_id")
    if not isinstance(shift_id, int):
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "shift_id must be an integer.", field="shift_id")

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
    if inst is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    directory = _load("oncall_directory.json")
    if not isinstance(directory, list):
        directory = []

    # TTL refresh rule (best-effort offline): if older than TTL, mark stale->active and update last_synced_at
    ttl_s = 900
    settings = _load("service_settings.json")
    if isinstance(settings, dict):
        v = settings.get("oncall_cache_ttl_seconds")
        if isinstance(v, int) and v > 0:
            ttl_s = v

    now = _now_utc()
    now_iso = _now_iso()

    row = next(
        (
            r
            for r in directory
            if isinstance(r, dict)
            and r.get("instance_id") == instance_id
            and r.get("entity_type") == "shift"
            and r.get("oncall_id") == shift_id
        ),
        None,
    )

    if row is None or row.get("status") == "deleted":
        _append_request_log("ok", used_instance_id=instance_id, meta={"shift_id": shift_id, "cache": "miss"})
        return {"instance_id": instance_id, "shift_id": shift_id, "shift": None, "cache": {"hit": False}}

    mutated = False
    ls = row.get("last_synced_at")
    last_dt = None
    if isinstance(ls, str) and ls.strip():
        s = ls.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            last_dt = datetime.datetime.fromisoformat(s)
            if last_dt.tzinfo is None:
                last_dt = last_dt.replace(tzinfo=datetime.timezone.utc)
            last_dt = last_dt.astimezone(datetime.timezone.utc)
        except Exception:
            last_dt = None

    if last_dt is None or (now - last_dt).total_seconds() > ttl_s:
        # refresh: offline, just bump sync time and ensure active if stale
        if row.get("status") == "stale":
            row["status"] = "active"
            mutated = True
        row["last_synced_at"] = now_iso
        row["updated_at"] = now_iso
        mutated = True

    if mutated:
        _save("oncall_directory.json", directory)

    _append_request_log("ok", used_instance_id=instance_id, meta={"shift_id": shift_id, "cache": "hit"})
    return {
        "instance_id": instance_id,
        "shift_id": shift_id,
        "shift": {
            "id": row.get("id"),
            "oncall_id": row.get("oncall_id"),
            "schedule_id": row.get("schedule_id"),
            "shift_start": row.get("shift_start"),
            "shift_end": row.get("shift_end"),
            "details": row.get("details"),
            "last_synced_at": row.get("last_synced_at"),
            "status": row.get("status"),
        },
        "cache": {"hit": True},
    }

def get_sift_analysis(instance_id, investigation_uuid, analysis_uuid, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_sift_analysis"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(8).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, inst_id=None, error_code=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": _new_id("rlog_"),
                    "service": "grafana_server",
                    "endpoint": endpoint,
                    "instance_id": inst_id,
                    "credential_id": None,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _now_iso(),
                    "meta": meta or {},
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate
    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id) is None:
        _append_request_log("error", inst_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a valid gfi_ ULID.", field="instance_id")
    uuid_re = re.compile(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$")
    if not isinstance(investigation_uuid, str) or not uuid_re.match(investigation_uuid):
        _append_request_log("error", inst_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "investigation_uuid must be a valid UUID.", field="investigation_uuid")
    if not isinstance(analysis_uuid, str) or not uuid_re.match(analysis_uuid):
        _append_request_log("error", inst_id=instance_id, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "analysis_uuid must be a valid UUID.", field="analysis_uuid")

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    inst = next((x for x in instances if isinstance(x, dict) and x.get("id") == instance_id), None)
    if not inst:
        _append_request_log("error", inst_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found.", instance_id=instance_id)
    if inst.get("status") != "active":
        _append_request_log("error", inst_id=instance_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance is disabled.", instance_id=instance_id)

    jobs = _load("observability_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Must match both UUIDs to a single job result, or trigger a refresh job.
    def _job_matches(j):
        return (
            isinstance(j, dict)
            and j.get("instance_id") == instance_id
            and j.get("job_type") == "sift_get_analysis"
            and j.get("sift_investigation_uuid") == investigation_uuid
            and j.get("sift_analysis_uuid") == analysis_uuid
            and j.get("status") == "succeeded"
            and isinstance(j.get("result"), dict)
        )

    match = next((j for j in jobs if _job_matches(j)), None)
    if not match:
        # Trigger refresh job (offline synthesis)
        now = _now_iso()
        job_id = _new_id("gjob_")
        job = {
            "id": job_id,
            "instance_id": instance_id,
            "job_type": "sift_get_analysis",
            "datasource_uid": None,
            "datasource_type": None,
            "query_text": None,
            "label_name": None,
            "series_selectors": [],
            "regex_filter": None,
            "time_start": None,
            "time_end": None,
            "step_seconds": None,
            "limit": None,
            "direction": None,
            "page_cursor": None,
            "page_limit": None,
            "sift_investigation_uuid": investigation_uuid,
            "sift_analysis_uuid": analysis_uuid,
            "assertion_entity": None,
            "result": None,
            "status": "queued",
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_by": None,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("observability_jobs.json", jobs)

        # Execute immediately (queued->running->succeeded)
        job["status"] = "running"
        job["started_at"] = _now_iso()
        job["updated_at"] = job["started_at"]
        _save("observability_jobs.json", jobs)

        try:
            payload = {
                "investigation_uuid": investigation_uuid,
                "analysis_uuid": analysis_uuid,
                "analysis": {"uuid": analysis_uuid, "status": "complete", "summary": None},
                "truncated": False,
            }
            b = json.dumps(payload, ensure_ascii=False).encode("utf-8")
            if len(b) > 1024 * 1024:
                payload = {"truncated": True, "summary": {"original_size_bytes": len(b)}}
            job["result"] = payload
            job["status"] = "succeeded"
            job["finished_at"] = _now_iso()
            job["updated_at"] = job["finished_at"]
            _save("observability_jobs.json", jobs)
            match = job
        except Exception as e:
            job["status"] = "failed"
            job["error_message"] = str(e)[:500]
            job["finished_at"] = _now_iso()
            job["updated_at"] = job["finished_at"]
            _save("observability_jobs.json", jobs)
            _append_request_log("error", inst_id=instance_id, error_code="CONFLICT")
            return _err("CONFLICT", "Failed to refresh Sift analysis", instance_id=instance_id)

    _append_request_log("ok", inst_id=instance_id, meta={"investigation_uuid": investigation_uuid, "analysis_uuid": analysis_uuid})
    return {"analysis": match["result"]}

def list_alert_rules(instance_id, label_selectors=None, page_cursor=None, page_limit=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error=None, credential_id=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if started is None:
            started = time.time()
        row = {
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "grafana",
            "endpoint": "list_alert_rules",
            "instance_id": instance_id,
            "credential_id": credential_id,
            "status": status,
            "error_code": (error or {}).get("code") if isinstance(error, dict) else None,
            "latency_ms": int(max(0, (time.time() - started) * 1000)),
            "timestamp": _now(),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()

    try:
        if not isinstance(instance_id, str) or not re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
            e = _err("VALIDATION_ERROR", "instance_id must be a valid gfi_ ULID.", field="instance_id")
            _log("error", e["error"], started=started)
            return e

        if label_selectors is not None:
            if not isinstance(label_selectors, list):
                e = _err("VALIDATION_ERROR", "label_selectors must be an array.", field="label_selectors")
                _log("error", e["error"], started=started)
                return e
            for i, s in enumerate(label_selectors):
                if not isinstance(s, dict):
                    e = _err("VALIDATION_ERROR", "Each label selector must be an object.", index=i)
                    _log("error", e["error"], started=started)
                    return e
                for k in ("name", "type", "value"):
                    if k not in s:
                        e = _err("VALIDATION_ERROR", f"Label selector missing '{k}'.", index=i)
                        _log("error", e["error"], started=started)
                        return e
                if not isinstance(s["name"], str) or not s["name"]:
                    e = _err("VALIDATION_ERROR", "Label selector name must be a non-empty string.", index=i, field="name")
                    _log("error", e["error"], started=started)
                    return e
                if s["type"] not in ("=", "!=", "=~", "!~"):
                    e = _err("VALIDATION_ERROR", "Label selector type is invalid.", index=i, field="type")
                    _log("error", e["error"], started=started)
                    return e
                if not isinstance(s["value"], str):
                    e = _err("VALIDATION_ERROR", "Label selector value must be a string.", index=i, field="value")
                    _log("error", e["error"], started=started)
                    return e

        if page_limit is None:
            page_limit = 100
        if not isinstance(page_limit, int) or page_limit < 1:
            e = _err("VALIDATION_ERROR", "page_limit must be an integer >= 1.", field="page_limit")
            _log("error", e["error"], started=started)
            return e
        # API-layer hard cap: 500
        if page_limit > 500:
            page_limit = 500

        offset = 0
        if page_cursor:
            if not isinstance(page_cursor, str):
                e = _err("VALIDATION_ERROR", "page_cursor must be a string.", field="page_cursor")
                _log("error", e["error"], started=started)
                return e
            try:
                raw = base64.urlsafe_b64decode(page_cursor.encode("utf-8") + b"===")
                obj = json.loads(raw.decode("utf-8"))
                if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("instance_id") != instance_id:
                    raise ValueError("bad cursor")
                offset = int(obj.get("offset", 0))
                if offset < 0:
                    raise ValueError("bad offset")
            except Exception:
                e = _err("VALIDATION_ERROR", "Invalid page_cursor.")
                _log("error", e["error"], started=started)
                return e

        instances = _load("grafana_instances.json")
        inst = next((x for x in instances if x.get("id") == instance_id), None)
        if not inst:
            e = _err("NOT_FOUND", "Grafana instance not found.", instance_id=instance_id)
            _log("error", e["error"], started=started)
            return e
        if inst.get("status") != "active":
            e = _err("UNAUTHORIZED", "Grafana instance is disabled.")
            _log("error", e["error"], started=started)
            return e

        resources = _load("grafana_resources.json")
        rules = [
            r for r in resources
            if r.get("instance_id") == instance_id and r.get("resource_type") == "alert_rule" and r.get("status") == "active"
        ]

        def _match_selector(labels, sel):
            if not isinstance(labels, dict):
                labels = {}
            key = sel["name"]
            op = sel["type"]
            val = sel["value"]
            actual = labels.get(key)
            actual_s = "" if actual is None else str(actual)
            if op == "=":
                return actual is not None and actual_s == val
            if op == "!=":
                return (actual is None) or (actual_s != val)
            if op in ("=~", "!~"):
                try:
                    ok = re.search(val, actual_s) is not None
                except re.error:
                    # Invalid regex is a validation error
                    raise ValueError(f"Invalid regex in selector for {key}")
                return ok if op == "=~" else (not ok)
            return True

        if label_selectors:
            filtered = []
            try:
                for r in rules:
                    labels = r.get("labels") if isinstance(r.get("labels"), dict) else {}
                    ok = True
                    for sel in label_selectors:
                        if not _match_selector(labels, sel):
                            ok = False
                            break
                    if ok:
                        filtered.append(r)
            except ValueError as ve:
                e = _err("VALIDATION_ERROR", str(ve))
                _log("error", e["error"], started=started)
                return e
            rules = filtered

        # Deterministic ordering: by folder_title, then title, then uid.
        def _k(r):
            return (
                (r.get("folder_title") or "").lower(),
                (r.get("title") or "").lower(),
                (r.get("uid") or "")
            )

        rules.sort(key=_k)

        total = len(rules)
        page = rules[offset:offset + page_limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = None
        if has_more:
            payload = {"v": 1, "instance_id": instance_id, "offset": next_offset}
            next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

        summaries = []
        for r in page:
            summaries.append({
                "uid": r.get("uid"),
                "title": r.get("title"),
                "state": r.get("state"),
                "labels": r.get("labels") if isinstance(r.get("labels"), dict) else {},
                "folder_uid": r.get("folder_uid"),
                "folder_title": r.get("folder_title"),
                "url": r.get("url"),
            })

        resp = {
            "items": summaries,
            "pagination": {
                "total": total,
                "page_limit": page_limit,
                "has_more": has_more,
                "next_cursor": next_cursor,
            }
        }
        _log("ok", started=started, meta={"returned": len(summaries), "total": total, "offset": offset})
        return resp
    except Exception as ex:
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _log("error", e["error"], started=started)
        return e

def list_contact_points(instance_id, name=None, limit=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _coerce_int(x):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        return None

    def _ensure_logs_and_enforce(kind, inst_id):
        # Best-effort usage logging + rate limiting if schema exists.
        # Return (ok:bool, err:dict|None, logs, log_file, counters_changed:bool)
        candidates = [
            "request_logs.json",
            "api_request_logs.json",
            "usage_logs.json",
            "audit_logs.json",
            "requests.json",
            "service_requests.json",
        ]
        log_file = None
        logs = None
        for fn in candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                log_file = fn
                logs = _load(fn)
                if not isinstance(logs, list):
                    logs = []
                break

        rate_limit_per_min = 120
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(minutes=1)
        used = 0
        if logs is not None:
            for r in logs:
                ts = _parse_dt(r.get("timestamp") or r.get("created_at") or r.get("ts"))
                if not ts:
                    continue
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
                if ts >= window_start and (r.get("instance_id") == inst_id or r.get("scope_id") == inst_id):
                    used += 1
        if used >= rate_limit_per_min:
            # still record the rejected call
            if logs is not None:
                logs.append({
                    "id": f"req_{uuid.uuid4().hex}",
                    "endpoint": kind,
                    "instance_id": inst_id,
                    "status": "RATE_LIMIT",
                    "timestamp": _now_iso(),
                    "latency_ms": 0
                })
                _save(log_file, logs)
            return False, _err("RATE_LIMIT", "Rate limit exceeded"), logs, log_file, False
        return True, None, logs, log_file, False

    t0 = time.time()

    # Validate inputs
    if not isinstance(instance_id, str) or not re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
        return _err("VALIDATION_ERROR", "instance_id must be a valid gfi_ ULID")
    if name is not None and not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string")
    lim = _coerce_int(limit)
    if limit is not None and lim is None:
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if lim is not None and (lim < 1 or lim > 1000):
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    ok, err, logs, log_file, _ = _ensure_logs_and_enforce("list_contact_points", instance_id)
    if not ok:
        return err

    instances = _load("grafana_instances.json")
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        # record request
        if logs is not None:
            logs.append({
                "id": f"req_{uuid.uuid4().hex}",
                "endpoint": "list_contact_points",
                "instance_id": instance_id,
                "status": "NOT_FOUND",
                "timestamp": _now_iso(),
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(log_file, logs)
        return _err("NOT_FOUND", "Grafana instance not found")
    if inst.get("status") != "active":
        if logs is not None:
            logs.append({
                "id": f"req_{uuid.uuid4().hex}",
                "endpoint": "list_contact_points",
                "instance_id": instance_id,
                "status": "UNAUTHORIZED",
                "timestamp": _now_iso(),
                "latency_ms": int((time.time() - t0) * 1000),
            })
            _save(log_file, logs)
        return _err("UNAUTHORIZED", "Instance is disabled")

    resources = _load("grafana_resources.json")
    rows = []
    for r in resources:
        if r.get("instance_id") != instance_id:
            continue
        if r.get("resource_type") != "contact_point":
            continue
        if r.get("status") != "active":
            continue
        if name is not None and r.get("name") != name:
            continue
        rows.append(r)

    # Deterministic ordering
    def _sort_key(r):
        return (
            (r.get("name") or ""),
            (r.get("uid") or ""),
            (r.get("id") or ""),
        )

    rows.sort(key=_sort_key)

    # Hard cap at 500 per business rule
    hard_cap = 500
    if lim is None:
        lim = hard_cap
    lim = min(lim, hard_cap)
    out = []
    for r in rows[:lim]:
        out.append({
            "id": r.get("id"),
            "uid": r.get("uid"),
            "name": r.get("name"),
            "type": r.get("type"),
            "url": r.get("url"),
        })

    if logs is not None:
        logs.append({
            "id": f"req_{uuid.uuid4().hex}",
            "endpoint": "list_contact_points",
            "instance_id": instance_id,
            "status": "OK",
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
            "result_count": len(out),
        })
        _save(log_file, logs)

    return {
        "contact_points": out,
        "meta": {
            "returned": len(out),
            "total_matched": len(rows),
            "limit": lim,
        },
    }

