            continue
        st = r.get("status")
        if status is not None and st != status:
            continue
        # list_incidents supports filtering by active/resolved; cancelled excluded unless explicitly asked (not supported here)
        if status is None and st not in ("active", "resolved"):
            continue
        drill = bool(r.get("is_drill", False))
        if not include_drill and drill:
            continue
        rows.append(r)

    # Sort: active first, then most recently updated
    def _dt_or_min(s):
        d = _parse_dt(s)
        if not d:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d

    def _sort_key(r):
        st = r.get("status")
        pri = 0 if st == "active" else 1
        upd = _dt_or_min(r.get("updated_at"))
        return (pri, -upd.timestamp(), r.get("id") or "")

    rows.sort(key=_sort_key)

    out = []
    for r in rows:
        out.append({
            "id": r.get("id"),
            "grafana_incident_id": r.get("grafana_incident_id"),
            "title": r.get("title"),
            "severity": r.get("severity"),
            "status": r.get("status"),
            "is_drill": bool(r.get("is_drill", False)),
            "labels": r.get("labels") if isinstance(r.get("labels"), dict) else {},
            "grafana_url": r.get("grafana_url"),
            "opened_at": r.get("opened_at"),
            "resolved_at": r.get("resolved_at"),
            "updated_at": r.get("updated_at"),
        })

    if logs is not None:
        logs.append({
            "id": f"req_{uuid.uuid4().hex}",
            "endpoint": "list_incidents",
            "instance_id": instance_id,
            "status": "OK",
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
            "result_count": len(out),
        })
        _save(log_file, logs)

    return {"incidents": out, "meta": {"returned": len(out), "total_matched": len(rows)}}

