    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _result_size_and_truncate(obj, limit_bytes=1024 * 1024):
        try:
            raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        except Exception:
            return {"truncated": True, "reason": "non_serializable"}
        if len(raw) <= limit_bytes:
            return obj
        if isinstance(obj, list):
            kept = []
            size = 0
            for it in obj:
                piece = json.dumps(it, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
                if size + len(piece) > int(limit_bytes * 0.9):
                    break
                kept.append(it)
                size += len(piece)
            return {"truncated": True, "original_bytes": len(raw), "items": kept}
        return {"truncated": True, "original_bytes": len(raw), "summary": "payload too large"}

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
