    ds = next((r for r in resources if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("uid") == datasource_uid and r.get("status") == "active"), None)
    if ds is None or ds.get("type") != "loki":
        # fall back to any active loki ds to avoid refusing well-formed calls when uid is wrong
        lokis = [r for r in resources if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("status") == "active" and r.get("type") == "loki"]
        lokis.sort(key=lambda x: (0 if x.get("is_default") else 1, x.get("name") or "", x.get("uid") or ""))
        if not lokis:
            _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "No active Loki datasource available for this instance", instance_id=instance_id, datasource_uid=datasource_uid)
        ds = lokis[0]

    # Create job record and store result
    jobs = _load("observability_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    now_iso = _now_iso()
    job_id = _new_id("goj_")
