        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("observability_jobs.json", jobs)

    try:
        # Heuristic label names based on stored query history: use existing jobs with label_name
        prior = _load("observability_jobs.json")
        label_names = set()
        if isinstance(prior, list):
            for r in prior:
                if isinstance(r, dict) and r.get("instance_id") == instance_id and isinstance(r.get("label_name"), str) and r.get("label_name"):
                    label_names.add(r["label_name"])
        # Always include some common Loki labels
        for k in ("job", "instance", "namespace", "pod", "container", "service", "level"):
