def list_oncall_schedules(instance_id, team_id=None, schedule_id=None, page_cursor=None, page_limit=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    req_ts = now.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        raw = f"{prefix}:{datetime.datetime.utcnow().isoformat()}:{os.getpid()}:{time.time()}".encode("utf-8")
        h = hashlib.sha256(raw).hexdigest()[:26]
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int(h, 16)
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return f"{prefix}_{''.join(out)}"

    def _record_call(status, used_instance_id=None, error_code=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append({
                "id": _gen_id("rql"),
                "endpoint": "list_oncall_schedules",
                "instance_id": used_instance_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": req_ts
            })
            _save("request_logs.json", logs)

    # validation
    if not isinstance(instance_id, str) or not re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
        _record_call("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a valid Grafana instance connector id.")
    if team_id is not None and (not isinstance(team_id, int) or team_id < 1):
        _record_call("error", instance_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "team_id must be an integer >= 1.")
    if schedule_id is not None and (not isinstance(schedule_id, int) or schedule_id < 1):
        _record_call("error", instance_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schedule_id must be an integer >= 1.")
    if page_limit is not None and (not isinstance(page_limit, int) or page_limit < 1 or page_limit > 200):
        _record_call("error", instance_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_limit must be between 1 and 200.")
    if page_cursor is not None and not isinstance(page_cursor, str):
        _record_call("error", instance_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_cursor must be a string.")

    insts = _load("grafana_instances.json")
    inst = None
    if isinstance(insts, list):
        for r in insts:
            if isinstance(r, dict) and r.get("id") == instance_id:
                inst = r
                break
    if not inst:
        _record_call("error", instance_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found.", instance_id=instance_id)
    if inst.get("status") != "active":
        _record_call("error", instance_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance is disabled.")

    # TTL refresh rule: if oldest relevant last_synced_at older than TTL, mark stale->active (simulated refresh)
    TTL_SECONDS = 300
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    directory = _load("oncall_directory.json")
    if not isinstance(directory, list):
        directory = []

    # simulate refresh: for schedule rows that are stale (status='stale') or last_synced_at too old, set last_synced_at=now and status='active'
    changed = False
    for row in directory:
        if not isinstance(row, dict):
            continue
        if row.get("instance_id") != instance_id or row.get("entity_type") != "schedule":
            continue
        ls = _parse_dt(row.get("last_synced_at")) if row.get("last_synced_at") else None
        too_old = (ls is None) or ((now - ls).total_seconds() > TTL_SECONDS)
        if row.get("status") in ("stale",) or too_old:
            # legal transitions: stale->active, active->stale only; we only do stale->active here, and active stays active
            if row.get("status") == "stale":
                row["status"] = "active"
            if too_old:
                row["last_synced_at"] = req_ts
            row["updated_at"] = req_ts
            changed = True
    if changed:
        _save("oncall_directory.json", directory)

    # filter active schedules
    rows = []
    for r in directory:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("entity_type") != "schedule":
            continue
        if r.get("status") != "active":
            continue
        if schedule_id is not None and r.get("oncall_id") != schedule_id:
            continue
        if team_id is not None and r.get("team_id") != team_id:
            continue
        rows.append(r)

    # sort deterministic by oncall_id then id
    rows.sort(key=lambda x: (x.get("oncall_id") if isinstance(x.get("oncall_id"), int) else 0, x.get("id") or ""))

    # pagination via opaque cursor = integer offset encoded as string
    limit = page_limit if page_limit is not None else 50
    try:
        offset = int(page_cursor) if page_cursor else 0
        if offset < 0:
            raise ValueError
    except ValueError:
        _record_call("error", instance_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_cursor is invalid.")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    # shape output: schedule summaries (and when schedule_id provided, include details)
    out = []
    for r in page:
        item = {
            "id": r.get("oncall_id"),
            "name": r.get("name"),
            "team_id": r.get("team_id"),
            "timezone": r.get("timezone"),
            "shift_ids": r.get("shift_ids") if isinstance(r.get("shift_ids"), list) else [],
        }
        if schedule_id is not None:
            item["details"] = r.get("details")
            item["last_synced_at"] = r.get("last_synced_at")
        out.append(item)

    _record_call("ok", instance_id, None)
    return {
        "schedules": out,
        "page": {
            "total": total,
            "count": len(out),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "page_limit": limit
        }
    }

