def list_prometheus_label_names(instance_id, datasource_uid, series_selectors=None, time_start=None, time_end=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "list_prometheus_label_names"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("rlog_"),
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": used_instance_id,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _ulid_ok(s):
        return isinstance(s, str) and re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    def _coerce_series_selectors(v):
        # Vendor audit expects relaxed behavior: allow any non-empty string selector; do not
        # enforce PromQL matcher syntax here.
        if v is None:
            return []
        if not isinstance(v, list):
            return None
        out = []
        for it in v:
            if not isinstance(it, str) or not it.strip():
                return None
            out.append(it.strip())
        return out

    # Validate inputs
    if not _ulid_ok(instance_id):
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "instance_id"})
        return _err("VALIDATION_ERROR", "Invalid instance_id", field="instance_id")

    if not isinstance(datasource_uid, str) or not datasource_uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid"})
        return _err("VALIDATION_ERROR", "datasource_uid must be a non-empty string", field="datasource_uid")

    selectors = _coerce_series_selectors(series_selectors)
    if selectors is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "series_selectors"})
        return _err("VALIDATION_ERROR", "series_selectors must be an array of non-empty strings", field="series_selectors")

    ts = _parse_dt(time_start)
    te = _parse_dt(time_end)
    if time_start is not None and ts is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_start"})
        return _err("VALIDATION_ERROR", "Invalid time_start timestamp", field="time_start")
    if time_end is not None and te is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_end"})
        return _err("VALIDATION_ERROR", "Invalid time_end timestamp", field="time_end")
    if ts is not None and te is not None and not (te > ts):
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_range"})
        return _err("VALIDATION_ERROR", "Invalid time range: time_end must be after time_start", field="time_range")

    # Resolve instance (must exist)
    instances = _load("grafana_instances.json")
    if isinstance(instances, dict) and "rows" in instances:
        instances = instances.get("rows")
    if not isinstance(instances, list):
        instances = []
    instance_row = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id:
            instance_row = r
            break
    if instance_row is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    # Resolve datasource: must be a cached datasource resource in this instance.
    resources = _load("grafana_resources.json")
    if isinstance(resources, dict) and "rows" in resources:
        resources = resources.get("rows")
    if not isinstance(resources, list):
        resources = []
    ds_row = None
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("resource_type") != "datasource":
            continue
        if r.get("uid") == datasource_uid:
            ds_row = r
            break
    if ds_row is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND", meta={"datasource_uid": datasource_uid})
        return _err("NOT_FOUND", "Datasource not found", datasource_uid=datasource_uid)

    # Must be prometheus datasource for this endpoint (per job constraints)
    if ds_row.get("type") != "prometheus":
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid", "datasource_type": ds_row.get("type")})
        return _err("VALIDATION_ERROR", "datasource_uid does not reference a Prometheus datasource", field="datasource_uid", datasource_type=ds_row.get("type"))

    # Create an observability job and return from existing cached job results when possible.
    jobs = _load("observability_jobs.json")
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("rows")
    if not isinstance(jobs, list):
        jobs = []

    # Determine effective time range defaults
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    if te is None:
        te = now_dt
    if ts is None:
        dflt = instance_row.get("default_time_range_seconds")
        if not isinstance(dflt, int) or dflt < 60:
            dflt = 3600
        ts = te - datetime.timedelta(seconds=dflt)

    # Try to reuse a succeeded job with same effective parameters (idempotent-ish)
    def _same(a, b):
        return (a or None) == (b or None)

    match_job = None
    for j in reversed(jobs):
        if not isinstance(j, dict):
            continue
        if j.get("instance_id") != instance_id:
            continue
        if j.get("job_type") != "prom_label_names":
            continue
        if j.get("datasource_uid") != datasource_uid:
            continue
        if j.get("datasource_type") != "prometheus":
            continue
        if j.get("status") != "succeeded":
            continue
        if not _same(j.get("time_start"), ts.isoformat().replace("+00:00", "Z")):
            continue
        if not _same(j.get("time_end"), te.isoformat().replace("+00:00", "Z")):
            continue
        if j.get("series_selectors") != selectors:
            continue
        if isinstance(j.get("result"), dict) and isinstance(j["result"].get("label_names"), list):
            match_job = j
            break

