    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _ulid_ok(s):
        return isinstance(s, str) and re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", s) is not None

    def _coerce_series_selectors(v):
        # Relaxed: accept any non-empty string selector; do not enforce PromQL matcher syntax.
        if v is None:
            return []
        if not isinstance(v, list):
            return None
        out = []
        for it in v:
