            continue
        if r.get("instance_id") != instance_id:
            continue
        labs = r.get("labels")
        if isinstance(labs, dict):
            v = labs.get(label_name)
            if isinstance(v, str) and v:
                values_set.add(v)
            elif isinstance(v, (int, float, bool)):
                values_set.add(str(v).lower() if isinstance(v, bool) else str(v))
            elif isinstance(v, list):
                for it in v:
