        if not isinstance(res, dict):
            continue
        # Prometheus responses typically carry "data" -> "result" with metric labelsets; we infer __name__
        data = res.get("data")
        if isinstance(data, dict):
            rr = data.get("result")
            if isinstance(rr, list):
                for it in rr:
                    if not isinstance(it, dict):
                        continue
                    metric = it.get("metric")
                    if isinstance(metric, dict):
                        nm = metric.get("__name__")
                        if isinstance(nm, str) and nm:
                            metas.append({"metric": nm, "type": None, "help": None, "unit": None})
    # Deduplicate by metric
    seen = set()
    uniq = []
    for m in metas:
        key = m.get("metric")
        if not isinstance(key, str):
            continue
        if key in seen:
            continue
        seen.add(key)
        uniq.append(m)

    uniq.sort(key=lambda x: x.get("metric") or "")
    if limit is not None:
        uniq = uniq[:limit]

    uniq, truncated = _truncate_result(uniq)
    job["result"] = {"metadata": uniq, "truncated": bool(truncated)} if isinstance(uniq, list) else uniq
    job["status"] = "succeeded"
    job["finished_at"] = _now_iso()
    job["updated_at"] = job["finished_at"]
    _save("observability_jobs.json", jobs)

    _append_request_log("ok", used_instance_id=instance_id, meta={"job_id": job_id, "returned": len(uniq) if isinstance(uniq, list) else None, "truncated": bool(truncated)})
    return {"metadata": uniq if isinstance(uniq, list) else [], "job_id": job_id}

def list_prometheus_metric_names(instance_id, datasource_uid, regex_filter=None, page_cursor=None, page_limit=None, **_extra):
    import json, os, datetime, time, hashlib, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
