    endpoint = "list_prometheus_metric_names"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("rlog_"),
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": used_instance_id,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id or "") is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "instance_id"})
        return _err("VALIDATION_ERROR", "Invalid instance_id", field="instance_id")
    if not isinstance(datasource_uid, str) or not datasource_uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid"})
        return _err("VALIDATION_ERROR", "datasource_uid must be a non-empty string", field="datasource_uid")

    if page_limit is None:
        page_limit = 200
    if not isinstance(page_limit, int) or page_limit < 1:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "page_limit"})
        return _err("VALIDATION_ERROR", "page_limit must be an integer >= 1", field="page_limit")
    if page_limit > 500:
        page_limit = 500

    start = 0
    if page_cursor is not None:
        if not isinstance(page_cursor, str) or not page_cursor:
            _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "page_cursor"})
            return _err("VALIDATION_ERROR", "page_cursor must be a non-empty string when provided", field="page_cursor")
        # Accept vendor-like opaque cursors: "p:<n>" OR base64("p:<n>")
        m = re.match(r"^p:(\d+)$", page_cursor)
        if not m:
            try:
                dec = base64.b64decode(page_cursor.encode("utf-8"), validate=True).decode("utf-8")
            except Exception:
                _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "page_cursor"})
                return _err("VALIDATION_ERROR", "Malformed page_cursor", field="page_cursor")
            m = re.match(r"^p:(\d+)$", dec)
            if not m:
                _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "page_cursor"})
                return _err("VALIDATION_ERROR", "Malformed page_cursor", field="page_cursor")
        start = int(m.group(1))

    rx = None
    if regex_filter is not None:
        if not isinstance(regex_filter, str):
            _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "regex_filter"})
            return _err("VALIDATION_ERROR", "regex_filter must be a string", field="regex_filter")
        try:
            rx = re.compile(regex_filter)
        except re.error:
            _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "regex_filter"})
            return _err("VALIDATION_ERROR", "regex_filter is not a valid regular expression", field="regex_filter")

    # Resolve instance and prometheus datasource
    instances = _load("grafana_instances.json")
    if isinstance(instances, dict) and "rows" in instances:
        instances = instances.get("rows")
    if not isinstance(instances, list):
        instances = []
    if not any(isinstance(r, dict) and r.get("id") == instance_id for r in instances):
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    resources = _load("grafana_resources.json")
    if isinstance(resources, dict) and "rows" in resources:
        resources = resources.get("rows")
    if not isinstance(resources, list):
        resources = []
    ds = None
    for r in resources:
        if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("uid") == datasource_uid:
            ds = r
            break
    if ds is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND", meta={"datasource_uid": datasource_uid})
        return _err("NOT_FOUND", "Datasource not found", datasource_uid=datasource_uid)
    if ds.get("type") != "prometheus":
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid", "datasource_type": ds.get("type")})
        return _err("VALIDATION_ERROR", "datasource_uid does not reference a Prometheus datasource", field="datasource_uid", datasource_type=ds.get("type"))

    # Offline metric name discovery: read from observability_jobs prom_query results (__name__)
    jobs = _load("observability_jobs.json")
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("rows")
    if not isinstance(jobs, list):
        jobs = []

    names_set = set()
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("instance_id") != instance_id:
            continue
        if j.get("datasource_uid") != datasource_uid:
            continue
        if j.get("job_type") != "prom_query":
            continue
        res = j.get("result")
        if not isinstance(res, dict):
            continue
        data = res.get("data")
        if not isinstance(data, dict):
            continue
        rr = data.get("result")
        if isinstance(rr, list):
            for it in rr:
                if not isinstance(it, dict):
                    continue
                metric = it.get("metric")
                if isinstance(metric, dict):
                    nm = metric.get("__name__")
                    if isinstance(nm, str) and nm:
                        names_set.add(nm)

    names = sorted(names_set)
    if rx is not None:
        names = [n for n in names if rx.search(n)]

    page = names[start : start + page_limit]
    next_offset = start + len(page)
    has_more = next_offset < len(names)
    next_cursor = None
    if has_more:
        nxt = f"p:{next_offset}"
        next_cursor = base64.b64encode(nxt.encode("utf-8")).decode("utf-8")

    _append_request_log("ok", used_instance_id=instance_id, meta={"returned": len(page), "total_filtered": len(names), "has_more": has_more})
    return {"metric_names": page, "has_more": has_more, "next_cursor": next_cursor}

def list_sift_investigations(instance_id, limit=None, **_extra):
