    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, used_instance_id=None, details=None):
        # Best-effort request log. Schema not provided; create file if missing.
        rec = {
            "id": "req_" + hashlib.sha256(f"{now}|list_sift_investigations|{instance_id}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "list_sift_investigations",
            "instance_id": used_instance_id or instance_id,
