            "latency_ms": int((time.time() - t0) * 1000),
        }
        if details is not None:
            rec["details"] = details
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(rec)
        _save("request_logs.json", logs)

    try:
        if not isinstance(instance_id, str) or not re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id):
            _log("error", details={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "instance_id must be a valid Grafana instance ULID (gfi_...)")

        if limit is None:
            limit_eff = 10
        else:
            if not isinstance(limit, int):
                _log("error", details={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "limit must be an integer")
            if limit < 1:
                _log("error", details={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "limit must be >= 1")
            limit_eff = limit

        instances = _load("grafana_instances.json")
        inst = next((r for r in instances if isinstance(r, dict) and r.get("id") == instance_id), None)
        if not inst:
            _log("error", details={"code": "NOT_FOUND"})
