        if inst.get("status") != "active":
            _log("error", details={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "Grafana instance is disabled", instance_id=instance_id)

        jobs = _load("observability_jobs.json")
        if not isinstance(jobs, list):
            jobs = []

        # Filter to Sift list jobs for this instance that have succeeded and contain investigations.
        sift_jobs = []
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("instance_id") != instance_id:
                continue
            if j.get("job_type") != "sift_list_investigations":
                continue
            if j.get("status") != "succeeded":
                continue
            res = j.get("result")
            if isinstance(res, dict):
                invs = res.get("investigations")
                if isinstance(invs, list):
                    sift_jobs.append(j)

        # Most recent job first
        def _dt(v):
            if not isinstance(v, str):
                return ""
            return v
        sift_jobs.sort(key=lambda j: (_dt(j.get("finished_at")) or _dt(j.get("updated_at")) or _dt(j.get("created_at"))), reverse=True)

        investigations = []
        if sift_jobs:
            res = sift_jobs[0].get("result") or {}
            invs = res.get("investigations") if isinstance(res, dict) else None
            if isinstance(invs, list):
                investigations = invs

        investigations_out = investigations[:limit_eff]

        _log("ok", used_instance_id=instance_id)
        return {
            "instance_id": instance_id,
            "limit": limit_eff,
            "count": len(investigations_out),
            "investigations": investigations_out,
            "source": {
                "kind": "cache",
                "job_id": (sift_jobs[0].get("id") if sift_jobs else None),
                "last_refreshed_at": (sift_jobs[0].get("finished_at") if sift_jobs else None),
            },
        }
    except Exception as e:
        _log("error", details={"code": "VALIDATION_ERROR", "exception": type(e).__name__})
        return _err("VALIDATION_ERROR", "Unexpected error")

