                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _truncate_result(obj, max_bytes=1024 * 1024):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        if len(raw) <= max_bytes:
            return obj, False
        if isinstance(obj, dict) and isinstance(obj.get("results"), list):
            base = dict(obj)
            base["truncated"] = True
            base["_truncated_bytes"] = len(raw)
            base["results"] = base["results"][:2000]
            return base, True
        return {"truncated": True, "_truncated_bytes": len(raw)}, True

    # Validate inputs
    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id or "") is None:
