            return _err("VALIDATION_ERROR", "step_seconds must be an integer >= 1", field="step_seconds")

    ts = _parse_dt(time_start)
    te = _parse_dt(time_end)
    if time_start is not None and ts is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_start"})
        return _err("VALIDATION_ERROR", "Invalid time_start timestamp", field="time_start")
    if time_end is not None and te is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_end"})
