        instances = instances.get("rows")
    if not isinstance(instances, list):
        instances = []
    instance_row = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id:
            instance_row = r
            break
    if instance_row is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    if te is None:
        te = now_dt
    if ts is None:
        dflt = instance_row.get("default_time_range_seconds")
        if not isinstance(dflt, int) or dflt < 60:
            dflt = 3600
        ts = te - datetime.timedelta(seconds=dflt)
    if not (te > ts):
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_range"})
        return _err("VALIDATION_ERROR", "Invalid time range: time_end must be after time_start", field="time_range")

    # Resolve Loki datasource
    resources = _load("grafana_resources.json")
    if isinstance(resources, dict) and "rows" in resources:
        resources = resources.get("rows")
    if not isinstance(resources, list):
        resources = []
    ds_row = None
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("resource_type") != "datasource":
            continue
        if r.get("uid") == datasource_uid:
            ds_row = r
            break
    if ds_row is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND", meta={"datasource_uid": datasource_uid})
        return _err("NOT_FOUND", "Datasource not found", datasource_uid=datasource_uid)
    if ds_row.get("type") != "loki":
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid", "datasource_type": ds_row.get("type")})
        return _err("VALIDATION_ERROR", "datasource_uid does not reference a Loki datasource", field="datasource_uid", datasource_type=ds_row.get("type"))

    # Create observability job capturing effective defaults
    jobs = _load("observability_jobs.json")
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("rows")
    if not isinstance(jobs, list):
        jobs = []

    job_id = _new_id("gjob_")
    ts_iso = ts.isoformat().replace("+00:00", "Z")
    te_iso = te.isoformat().replace("+00:00", "Z")
    now_iso = _now_iso()
    job = {
        "id": job_id,
        "instance_id": instance_id,
        "job_type": "loki_query",
        "datasource_uid": datasource_uid,
        "datasource_type": "loki",
        "query_text": query_text,
        "label_name": None,
        "series_selectors": [],
        "regex_filter": None,
        "time_start": ts_iso,
        "time_end": te_iso,
        "step_seconds": step_seconds,
        "limit": limit,
        "direction": direction,
        "page_cursor": None,
        "page_limit": None,
        "sift_investigation_uuid": None,
        "sift_analysis_uuid": None,
        "assertion_entity": None,
        "result": None,
        "status": "queued",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_by": _extra.get("created_by") if isinstance(_extra, dict) else None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("observability_jobs.json", jobs)

    # Execute offline with best-effort deterministic synthetic results (cannot reach Grafana)
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("observability_jobs.json", jobs)

    # Use incident activities/comments as a stand-in for log lines, filtered by simple substring heuristics
    incs = _load("incidents.json")
    if isinstance(incs, dict) and "rows" in incs:
        incs = incs.get("rows")
    if not isinstance(incs, list):
        incs = []
    acts = _load("incident_activities.json")
    if isinstance(acts, dict) and "rows" in acts:
        acts = acts.get("rows")
    if not isinstance(acts, list):
        acts = []

    wanted = query_text.lower()
    results = []
    # deterministic pseudo timestamps within range
    span = int((te - ts).total_seconds())
    idx = 0
    for a in acts:
        if not isinstance(a, dict):
            continue
        inc_id = a.get("incident_id")
        if not inc_id:
            continue
        inc = None
        for ir in incs:
            if isinstance(ir, dict) and ir.get("id") == inc_id and ir.get("instance_id") == instance_id:
                inc = ir
                break
        if inc is None:
            continue
        body = a.get("body") if isinstance(a.get("body"), str) else ""
        if wanted and wanted not in body.lower():
            # allow selector-like queries "{...}" to match everything
            if not query_text.strip().startswith("{"):
                continue
        # timestamp
        offset = (idx * 13) % (span + 1) if span >= 0 else 0
        ts_item = (te - datetime.timedelta(seconds=offset)) if direction == "backward" else (ts + datetime.timedelta(seconds=offset))
        results.append(
            {
                "timestamp": ts_item.isoformat().replace("+00:00", "Z"),
                "labels": {"incident_id": inc.get("grafana_incident_id") or inc.get("id"), "activity_type": a.get("activity_type") or "comment"},
                "line": body,
            }
        )
        idx += 1
        if len(results) >= limit:
            break

    payload = {"results": results}
    payload, truncated = _truncate_result(payload)
    if isinstance(payload, dict) and truncated:
        payload["truncated"] = True

    job["result"] = payload
    job["status"] = "succeeded"
    job["finished_at"] = _now_iso()
    job["updated_at"] = job["finished_at"]
    _save("observability_jobs.json", jobs)

    _append_request_log("ok", used_instance_id=instance_id, meta={"job_id": job_id, "returned": len(results), "truncated": bool(payload.get("truncated")) if isinstance(payload, dict) else False})
    return {"results": results, "job_id": job_id}

def query_loki_stats(instance_id, datasource_uid, query_text, time_start=None, time_end=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "query_loki_stats"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("rlog_"),
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": used_instance_id,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _is_pure_selector(q):
        if not isinstance(q, str):
            return False
        s = q.strip()
        if not (s.startswith("{") and s.endswith("}")):
            return False
        bad_tokens = ["|=", "|~", "!=", "|>", "| json", "| logfmt", "| regexp", "| pattern", "| unwrap", "| line_format", "| label_format"]
        for bt in bad_tokens:
            if bt in s:
                return False
        return True

    # Validate inputs
    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id or "") is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "instance_id"})
        return _err("VALIDATION_ERROR", "Invalid instance_id", field="instance_id")
    if not isinstance(datasource_uid, str) or not datasource_uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid"})
        return _err("VALIDATION_ERROR", "datasource_uid must be a non-empty string", field="datasource_uid")
    if not isinstance(query_text, str) or not query_text.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "query_text"})
        return _err("VALIDATION_ERROR", "query_text must be a non-empty string", field="query_text")
    if not _is_pure_selector(query_text):
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "query_text"})
        return _err("VALIDATION_ERROR", "query_text must be a simple LogQL label selector (no pipelines/line filters)", field="query_text")

    ts = _parse_dt(time_start)
    te = _parse_dt(time_end)
    if time_start is not None and ts is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_start"})
        return _err("VALIDATION_ERROR", "Invalid time_start timestamp", field="time_start")
    if time_end is not None and te is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_end"})
        return _err("VALIDATION_ERROR", "Invalid time_end timestamp", field="time_end")

    # Resolve instance and defaults
    instances = _load("grafana_instances.json")
    if isinstance(instances, dict) and "rows" in instances:
        instances = instances.get("rows")
    if not isinstance(instances, list):
        instances = []
    instance_row = None
    for r in instances:
        if isinstance(r, dict) and r.get("id") == instance_id:
            instance_row = r
            break
    if instance_row is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    if te is None:
        te = now_dt
    if ts is None:
        dflt = instance_row.get("default_time_range_seconds")
        if not isinstance(dflt, int) or dflt < 60:
            dflt = 3600
        ts = te - datetime.timedelta(seconds=dflt)
    if not (te > ts):
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_range"})
        return _err("VALIDATION_ERROR", "Invalid time range: time_end must be after time_start", field="time_range")

    # Resolve Loki datasource
    resources = _load("grafana_resources.json")
    if isinstance(resources, dict) and "rows" in resources:
        resources = resources.get("rows")
    if not isinstance(resources, list):
        resources = []
    ds_row = None
    for r in resources:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("uid") == datasource_uid:
            ds_row = r
            break
    if ds_row is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND", meta={"datasource_uid": datasource_uid})
        return _err("NOT_FOUND", "Datasource not found", datasource_uid=datasource_uid)
    if ds_row.get("type") != "loki":
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid", "datasource_type": ds_row.get("type")})
        return _err("VALIDATION_ERROR", "datasource_uid does not reference a Loki datasource", field="datasource_uid", datasource_type=ds_row.get("type"))

    # Create job capturing effective defaults
    jobs = _load("observability_jobs.json")
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("rows")
    if not isinstance(jobs, list):
        jobs = []

    job_id = _new_id("gjob_")
    now_iso = _now_iso()
    ts_iso = ts.isoformat().replace("+00:00", "Z")
    te_iso = te.isoformat().replace("+00:00", "Z")
    job = {
        "id": job_id,
        "instance_id": instance_id,
        "job_type": "loki_stats",
        "datasource_uid": datasource_uid,
        "datasource_type": "loki",
        "query_text": query_text.strip(),
        "label_name": None,
        "series_selectors": [],
        "regex_filter": None,
        "time_start": ts_iso,
        "time_end": te_iso,
        "step_seconds": None,
        "limit": None,
        "direction": None,
        "page_cursor": None,
        "page_limit": None,
        "sift_investigation_uuid": None,
        "sift_analysis_uuid": None,
        "assertion_entity": None,
        "result": None,
        "status": "queued",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_by": _extra.get("created_by") if isinstance(_extra, dict) else None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("observability_jobs.json", jobs)

    # Execute offline stats: count incident_activities as "entries"; unique incidents as "streams"
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("observability_jobs.json", jobs)

    incs = _load("incidents.json")
    if isinstance(incs, dict) and "rows" in incs:
        incs = incs.get("rows")
    if not isinstance(incs, list):
        incs = []
    acts = _load("incident_activities.json")
    if isinstance(acts, dict) and "rows" in acts:
        acts = acts.get("rows")
    if not isinstance(acts, list):
        acts = []

    inc_ids = set()
    entries = 0
    bytes_total = 0
    for a in acts:
        if not isinstance(a, dict):
            continue
        inc_id = a.get("incident_id")
        if not isinstance(inc_id, str):
            continue
        # ensure incident belongs to instance
        ok = False
        for ir in incs:
            if isinstance(ir, dict) and ir.get("id") == inc_id and ir.get("instance_id") == instance_id:
                ok = True
                break
        if not ok:
            continue
        inc_ids.add(inc_id)
        entries += 1
        body = a.get("body") if isinstance(a.get("body"), str) else ""
        bytes_total += len(body.encode("utf-8"))

    stats = {"streams": len(inc_ids), "chunks": max(1, len(inc_ids)), "entries": entries, "bytes": bytes_total}
    job["result"] = {"stats": stats}
    job["status"] = "succeeded"
    job["finished_at"] = _now_iso()
    job["updated_at"] = job["finished_at"]
    _save("observability_jobs.json", jobs)

    _append_request_log("ok", used_instance_id=instance_id, meta={"job_id": job_id, **stats})
    return {"stats": stats, "job_id": job_id}

def query_prometheus(instance_id, datasource_uid, query, query_type, time=None, time_start=None, time_end=None, step_seconds=None, **_extra):
    import json, os, datetime, time as _time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "query_prometheus"
    t0 = _time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        raw = f"{_time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, used_instance_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("rlog_"),
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": used_instance_id,
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((_time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    # Validate inputs
    if not isinstance(instance_id, str) or re.match(r"^gfi_[0-9A-HJKMNP-TV-Z]{26}$", instance_id or "") is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "instance_id"})
        return _err("VALIDATION_ERROR", "Invalid instance_id", field="instance_id")
    if not isinstance(datasource_uid, str) or not datasource_uid.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid"})
        return _err("VALIDATION_ERROR", "datasource_uid must be a non-empty string", field="datasource_uid")
    if not isinstance(query, str) or not query.strip():
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "query"})
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")
    if query_type not in ("instant", "range"):
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "query_type"})
        return _err("VALIDATION_ERROR", "query_type must be one of: instant, range", field="query_type")

    t_instant = _parse_dt(time)
    ts = _parse_dt(time_start)
    te = _parse_dt(time_end)

    if query_type == "instant":
        if time is None or t_instant is None:
            _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time"})
            return _err("VALIDATION_ERROR", "time is required for instant queries and must be a valid RFC3339 timestamp", field="time")
        # ignore range params if present
    else:
        if ts is None or te is None:
            _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_range"})
            return _err("VALIDATION_ERROR", "time_start and time_end are required for range queries and must be valid RFC3339 timestamps", field="time_range")
        if not (te > ts):
            _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "time_range"})
            return _err("VALIDATION_ERROR", "Invalid time range: time_end must be after time_start", field="time_range")
        if step_seconds is None or not isinstance(step_seconds, int) or step_seconds < 1:
            _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "step_seconds"})
            return _err("VALIDATION_ERROR", "step_seconds is required for range queries and must be an integer >= 1", field="step_seconds")

    # Resolve instance
    instances = _load("grafana_instances.json")
    if isinstance(instances, dict) and "rows" in instances:
        instances = instances.get("rows")
    if not isinstance(instances, list):
        instances = []
    if not any(isinstance(r, dict) and r.get("id") == instance_id for r in instances):
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    # Resolve prometheus datasource
    resources = _load("grafana_resources.json")
    if isinstance(resources, dict) and "rows" in resources:
        resources = resources.get("rows")
    if not isinstance(resources, list):
        resources = []
    ds = None
    for r in resources:
        if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("resource_type") == "datasource" and r.get("uid") == datasource_uid:
            ds = r
            break
    if ds is None:
        _append_request_log("error", used_instance_id=instance_id, error_code="NOT_FOUND", meta={"datasource_uid": datasource_uid})
        return _err("NOT_FOUND", "Datasource not found", datasource_uid=datasource_uid)
    if ds.get("type") != "prometheus":
        _append_request_log("error", used_instance_id=instance_id, error_code="VALIDATION_ERROR", meta={"field": "datasource_uid", "datasource_type": ds.get("type")})
        return _err("VALIDATION_ERROR", "datasource_uid does not reference a Prometheus datasource", field="datasource_uid", datasource_type=ds.get("type"))

    # Create job
    jobs = _load("observability_jobs.json")
    if isinstance(jobs, dict) and "rows" in jobs:
        jobs = jobs.get("rows")
    if not isinstance(jobs, list):
        jobs = []

    job_id = _new_id("gjob_")
    now_iso = _now_iso()
    job = {
        "id": job_id,
        "instance_id": instance_id,
        "job_type": "prom_query",
        "datasource_uid": datasource_uid,
        "datasource_type": "prometheus",
        "query_text": query.strip(),
        "label_name": None,
        "series_selectors": [],
        "regex_filter": None,
        "time_start": ts.isoformat().replace("+00:00", "Z") if ts else None,
        "time_end": te.isoformat().replace("+00:00", "Z") if te else None,
        "step_seconds": step_seconds,
        "limit": None,
        "direction": None,
        "page_cursor": None,
        "page_limit": None,
        "sift_investigation_uuid": None,
        "sift_analysis_uuid": None,
        "assertion_entity": None,
        "result": None,
        "status": "queued",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_by": _extra.get("created_by") if isinstance(_extra, dict) else None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("observability_jobs.json", jobs)

    # Execute offline: produce deterministic, Prometheus-shaped response
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("observability_jobs.json", jobs)

    # Try to infer metric name from query (best-effort)
    q = query.strip()
    mname = None
    m = re.match(r"^([a-zA-Z_:][a-zA-Z0-9_:]*)", q)
    if m:
        mname = m.group(1)

    if query_type == "instant":
        t_iso = t_instant.isoformat().replace("+00:00", "Z")
        value = "0"
        result = [{"metric": {"__name__": mname or ""}, "value": [t_iso, value]}]
        payload = {"status": "success", "data": {"resultType": "vector", "result": result}}
    else:
        # range: generate a small series capped to 120 points
        start = ts
        end = te
        step = int(step_seconds)
        total_pts = int((end - start).total_seconds() // step) + 1
        total_pts = max(1, min(total_pts, 120))
        values = []
        for i in range(total_pts):
            tt = start + datetime.timedelta(seconds=i * step)
            values.append([tt.isoformat().replace("+00:00", "Z"), "0"])
        result = [{"metric": {"__name__": mname or ""}, "values": values}]
        payload = {"status": "success", "data": {"resultType": "matrix", "result": result}}

    # Truncate if needed
    raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    if len(raw) > 1024 * 1024:
        payload = {"status": "success", "data": {"truncated": True, "_truncated_bytes": len(raw), "resultType": payload.get("data", {}).get("resultType"), "result": []}}

    job["result"] = payload
    job["status"] = "succeeded"
    job["finished_at"] = _now_iso()
    job["updated_at"] = job["finished_at"]
    _save("observability_jobs.json", jobs)

    _append_request_log("ok", used_instance_id=instance_id, meta={"job_id": job_id, "query_type": query_type})
    return {"result": payload, "job_id": job_id}

def search_dashboards(instance_id, query=None, folder_uid=None, tags=None, limit=None, page_cursor=None, **_extra):
    import json, os, datetime, time as _time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = _time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ulid_like(prefix, s):
        if not isinstance(s, str):
            return False
        return re.match(r"^%s_[0-9A-HJKMNP-TV-Z]{26}$" % re.escape(prefix), s) is not None

    def _record_request(endpoint, instance_id_used, status_code, error_code=None):
        row = {
            "id": "rql_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(_time.time())).encode("utf-8")).hexdigest()[:26],
            "endpoint": endpoint,
            "instance_id": instance_id_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((_time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    def _check_limits(instance_row):
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        rpm = instance_row.get("rate_limit_rpm", 120)
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 120
        if rpm > 0:
            cutoff = (now - datetime.timedelta(seconds=60)).isoformat()
            recent = 0
            for r in logs:
                if r.get("instance_id") != instance_row.get("id"):
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded for this Grafana instance connector.")
        qpd = instance_row.get("quota_per_day", 20000)
        try:
            qpd = int(qpd)
        except Exception:
            qpd = 20000
        if qpd > 0:
            day_cut = (now - datetime.timedelta(days=1)).isoformat()
            used = 0
            for r in logs:
                if r.get("instance_id") != instance_row.get("id"):
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= day_cut:
                    used += 1
            if used >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this Grafana instance connector.")
        return None

    if not _ulid_like("gfi", instance_id):
        _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a valid Grafana instance ULID (gfi_...).")

    if query is not None and not isinstance(query, str):
        _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a string when provided.")
    if folder_uid is not None and not isinstance(folder_uid, str):
        _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "folder_uid must be a string when provided.")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of strings when provided.")
    if limit is None:
        limit = 50
    try:
        limit = int(limit)
    except Exception:
        _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1:
        _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be >= 1.")

    start = 0
    if page_cursor is not None:
        if not isinstance(page_cursor, str) or not page_cursor:
            _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_cursor is malformed.")
        # cursor format: "v1:<base64url(json:{start:int})>"
        if not page_cursor.startswith("v1:"):
            _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_cursor is malformed.")
        b = page_cursor[3:]
        try:
            padded = b + "=" * (-len(b) % 4)
            data = json.loads(base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8"))
            start = int(data.get("start", 0))
            if start < 0:
                raise ValueError()
        except Exception:
            _record_request("search_dashboards", instance_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_cursor is malformed.")

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        _record_request("search_dashboards", instance_id, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found.")
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        _record_request("search_dashboards", instance_id, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found.")
    if inst.get("status") != "active":
        _record_request("search_dashboards", instance_id, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance connector is disabled.")

    limerr = _check_limits(inst)
    if limerr:
        _record_request("search_dashboards", instance_id, 429, limerr["error"]["code"])
        return limerr

    resources = _load("grafana_resources.json")
    if not isinstance(resources, list):
        resources = []

    q = (query or "").strip().lower()
    tagset = set([t.strip() for t in (tags or []) if isinstance(t, str) and t.strip()])

    matches = []
    for r in resources:
        if r.get("instance_id") != instance_id:
            continue
        if r.get("resource_type") != "dashboard":
            continue
        if r.get("status") != "active":
            continue
        if folder_uid is not None and r.get("folder_uid") != folder_uid:
            continue
        rt = r.get("tags") if isinstance(r.get("tags"), list) else []
        if tagset:
            if not set([str(x) for x in rt]).issuperset(tagset):
                continue
        title = (r.get("title") or "").strip()
        # business rule: title ILIKE query OR tags contains query
        if q:
            in_title = q in title.lower()
            in_tags = any(q in str(t).lower() for t in rt)
            if not (in_title or in_tags):
                continue
        matches.append(r)

    # deterministic sort: folder_title, title, uid
    def _k(r):
        return ((r.get("folder_title") or "").lower(), (r.get("title") or "").lower(), (r.get("uid") or ""))
    matches.sort(key=_k)

    total = len(matches)
    page = matches[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        payload = {"start": start + limit}
        b = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = "v1:" + b

    results = []
    for r in page:
        results.append({
            "uid": r.get("uid"),
            "title": r.get("title"),
            "folder_uid": r.get("folder_uid"),
            "folder_title": r.get("folder_title"),
            "tags": r.get("tags") if isinstance(r.get("tags"), list) else [],
            "url": r.get("url"),
        })

    _record_request("search_dashboards", instance_id, 200, None)
    return {
        "dashboards": results,
        "pagination": {
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "page_cursor": page_cursor,
            "limit": limit,
            "offset": start,
        },
    }

def update_dashboard(instance_id, title, spec, uid=None, folder_uid=None, tags=None, spec_etag=None, **_extra):
    import json, os, datetime, time as _time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
