        return re.match(r"^%s_[0-9A-HJKMNP-TV-Z]{26}$" % re.escape(prefix), s) is not None

    def _record_request(endpoint, instance_id_used, status_code, error_code=None):
        row = {
            "id": "rql_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(_time.time())).encode("utf-8")).hexdigest()[:26],
            "endpoint": endpoint,
            "instance_id": instance_id_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((_time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    def _check_limits(instance_row):
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        rpm = instance_row.get("rate_limit_rpm", 60)
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 60
        if rpm > 0:
            cutoff = (now - datetime.timedelta(seconds=60)).isoformat()
            recent = 0
            for r in logs:
                if r.get("instance_id") != instance_row.get("id"):
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded for this Grafana instance connector.")
        qpd = instance_row.get("quota_per_day", 5000)
        try:
            qpd = int(qpd)
        except Exception:
            qpd = 5000
        if qpd > 0:
            day_cut = (now - datetime.timedelta(days=1)).isoformat()
            used = 0
            for r in logs:
                if r.get("instance_id") != instance_row.get("id"):
                    continue
                ts = r.get("timestamp")
                if isinstance(ts, str) and ts >= day_cut:
                    used += 1
            if used >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this Grafana instance connector.")
        return None

    if not _ulid_like("gfi", instance_id):
        _record_request("update_dashboard", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a valid Grafana instance ULID (gfi_...).")
    if uid is not None and (not isinstance(uid, str) or not uid.strip()):
        _record_request("update_dashboard", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "uid must be a non-empty string when provided.")
    if not isinstance(title, str) or not title.strip():
        _record_request("update_dashboard", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if not isinstance(spec, dict):
        _record_request("update_dashboard", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spec must be an object (dashboard JSON model).")
    if folder_uid is not None and not isinstance(folder_uid, str):
        _record_request("update_dashboard", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "folder_uid must be a string when provided.")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            _record_request("update_dashboard", instance_id, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of strings when provided.")
    if spec_etag is not None and not isinstance(spec_etag, str):
        _record_request("update_dashboard", instance_id, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spec_etag must be a string when provided.")

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        _record_request("update_dashboard", instance_id, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found.")
    inst = next((r for r in instances if r.get("id") == instance_id), None)
    if not inst:
        _record_request("update_dashboard", instance_id, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found.")
    if inst.get("status") != "active":
        _record_request("update_dashboard", instance_id, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Grafana instance connector is disabled.")

    limerr = _check_limits(inst)
    if limerr:
        _record_request("update_dashboard", instance_id, 429, limerr["error"]["code"])
        return limerr

    resources = _load("grafana_resources.json")
    if not isinstance(resources, list):
        resources = []

    now = _now_iso()

    def _new_gfr_id():
        raw = hashlib.sha256((instance_id + "|dashboard|" + (uid or "") + "|" + title + "|" + now + "|" + str(_time.time())).encode("utf-8")).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(raw[:16], "big")
        out = []
        for _ in range(26):
            n, rem = divmod(n, 32)
            out.append(alphabet[rem])
        return "gfr_" + "".join(out)

    def _gen_uid_from_spec():
        raw = hashlib.sha256(json.dumps(spec, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
        # Grafana UIDs are often short; keep deterministic 12 chars
        return raw[:12]

    # Find existing dashboard by uid if provided
    existing = None
    if uid is not None:
        for r in resources:
            if r.get("instance_id") == instance_id and r.get("resource_type") == "dashboard" and r.get("uid") == uid:
                existing = r
                break

    # optimistic concurrency: if updating existing and spec_etag provided, must match
    if existing is not None and spec_etag is not None:
        if existing.get("spec_etag") is not None and existing.get("spec_etag") != spec_etag:
            _record_request("update_dashboard", instance_id, 409, "CONFLICT")
            return _err("CONFLICT", "spec_etag does not match current dashboard version.", current_spec_etag=existing.get("spec_etag"))

    # Determine resulting uid (Grafana response simulated)
    resulting_uid = uid if uid is not None else _gen_uid_from_spec()

    # Enforce uniqueness (instance_id, resource_type, uid) where uid not null
    for r in resources:
        if r is existing:
            continue
        if r.get("instance_id") == instance_id and r.get("resource_type") == "dashboard" and r.get("uid") == resulting_uid:
            # If creating and collision, treat as update of that row (idempotent-ish)
            existing = r
            break

    # Build new/updated spec_etag (Grafana would return version); if caller passed, preserve unless replaced
    computed_etag = hashlib.sha256(json.dumps(spec, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()

    # Upsert row
    if existing is None:
        row = {
            "id": _new_gfr_id(),
            "instance_id": instance_id,
            "resource_type": "dashboard",
            "uid": resulting_uid,
            "numeric_id": None,
            "name": None,
            "title": title,
            "folder_uid": folder_uid,
            "folder_title": None,
            "type": None,
            "url": (inst.get("base_url") or "").rstrip("/") + "/d/" + resulting_uid if inst.get("base_url") else None,
            "tags": tags if isinstance(tags, list) else [],
            "labels": {},
            "is_default": False,
            "state": None,
            "spec": spec,
            "spec_etag": computed_etag,
            "last_synced_at": now,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        resources.append(row)
        _save("grafana_resources.json", resources)
        _record_request("update_dashboard", instance_id, 200, None)
        return {"dashboard": {"uid": row["uid"], "title": row["title"], "folder_uid": row.get("folder_uid"), "tags": row.get("tags", []), "url": row.get("url"), "spec_etag": row.get("spec_etag")}, "created": True}
    else:
        # lifecycle: allow moving from stale/deleted? schema: deleted has no transitions; enforce
        if existing.get("status") == "deleted":
            _record_request("update_dashboard", instance_id, 409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot update a deleted dashboard cache row.")
        # Update fields; set active
        existing["uid"] = resulting_uid
        existing["title"] = title
        existing["folder_uid"] = folder_uid
        if tags is not None:
            existing["tags"] = tags
        elif not isinstance(existing.get("tags"), list):
            existing["tags"] = []
        existing["spec"] = spec
        existing["spec_etag"] = computed_etag
        existing["last_synced_at"] = now
        existing["status"] = "active"
        existing["url"] = (inst.get("base_url") or "").rstrip("/") + "/d/" + resulting_uid if inst.get("base_url") else existing.get("url")
        existing["updated_at"] = now
        _save("grafana_resources.json", resources)
        _record_request("update_dashboard", instance_id, 200, None)
        return {"dashboard": {"uid": existing["uid"], "title": existing["title"], "folder_uid": existing.get("folder_uid"), "tags": existing.get("tags", []), "url": existing.get("url"), "spec_etag": existing.get("spec_etag")}, "created": False}

def list_grafana_instances(status=None, page_cursor=None, page_limit=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "list_grafana_instances"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(16).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status_str, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _new_id("rlog_"),
                "service": "grafana_server",
                "endpoint": endpoint,
                "instance_id": None,
                "credential_id": None,
                "status": status_str,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    # Validate
    if status is not None and status not in ("active", "disabled"):
        _append_request_log("error", error_code="VALIDATION_ERROR", meta={"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled", field="status")

    if page_limit is None:
        page_limit = 50
    if not isinstance(page_limit, int):
        _append_request_log("error", error_code="VALIDATION_ERROR", meta={"field": "page_limit"})
        return _err("VALIDATION_ERROR", "page_limit must be an integer", field="page_limit")
    if page_limit < 1 or page_limit > 200:
        _append_request_log("error", error_code="VALIDATION_ERROR", meta={"field": "page_limit"})
        return _err("VALIDATION_ERROR", "page_limit must be between 1 and 200", field="page_limit")

    start = 0
    if page_cursor is not None:
        if not isinstance(page_cursor, str) or not page_cursor:
            _append_request_log("error", error_code="VALIDATION_ERROR", meta={"field": "page_cursor"})
            return _err("VALIDATION_ERROR", "page_cursor must be a non-empty string when provided", field="page_cursor")
        m = re.match(r"^offset:(\d+)$", page_cursor)
        if not m:
            _append_request_log("error", error_code="VALIDATION_ERROR", meta={"field": "page_cursor"})
            return _err("VALIDATION_ERROR", "Malformed page_cursor", field="page_cursor")
        start = int(m.group(1))

    inst = _load("grafana_instances.json")
    if isinstance(inst, dict) and "rows" in inst:
        inst = inst.get("rows")
    if not isinstance(inst, list):
        inst = []

    rows = []
    for r in inst:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    total = len(rows)
    page = rows[start : start + page_limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    out_rows = []
    for r in page:
        out_rows.append(
            {
                "id": r.get("id"),
                "name": r.get("name"),
                "base_url": r.get("base_url"),
                "org_id": r.get("org_id"),
                "auth_type": r.get("auth_type"),
                "status": r.get("status"),
                "default_time_range_seconds": r.get("default_time_range_seconds"),
