def update_grafana_instance(instance_id, name=None, base_url=None, org_id=None, auth_type=None, auth_ref=None, default_time_range_seconds=None, status=None, **_extra):
    import json, os, datetime, re, time, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_grafana_instance"
    audit_file_candidates = ["request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"]
    audit_file = next((n for n in audit_file_candidates if os.path.exists(os.path.join(_DB, n))), "request_logs.json")
    logs = _load(audit_file)

    def _log(status_s, credential_used=None, error_code=None):
        dt = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": dt,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential": credential_used,
        }
        if error_code:
            row["error_code"] = error_code
        if isinstance(logs, list):
            logs.append(row)
            _save(audit_file, logs)

    # Validate instance_id
    if not isinstance(instance_id, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a string")
    if not re.match(r"^gfi_[0-9A-Z]{26}$", instance_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "instance_id must be a gfi_ ULID", field="instance_id")

    # Validate provided fields
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    def _valid_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    if base_url is not None and not _valid_url(base_url):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "base_url must be a valid URL", field="base_url")

    if org_id is not None:
        if not isinstance(org_id, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "org_id must be an integer", field="org_id")
        if org_id < 1:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "org_id must be >= 1", field="org_id")

    # Tool enum differs from stored enum; map to stored values
    auth_map = {
        "api_token": "api_token",
        "basic_auth": "basic",
        "oauth_client_credentials": "oauth_client",
    }
    if auth_type is not None:
        if not isinstance(auth_type, str) or auth_type not in auth_map:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "auth_type must be one of api_token, basic_auth, oauth_client_credentials", field="auth_type")

    if auth_ref is not None and not isinstance(auth_ref, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "auth_ref must be a string", field="auth_ref")

    if default_time_range_seconds is not None:
        if not isinstance(default_time_range_seconds, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_time_range_seconds must be an integer", field="default_time_range_seconds")
        if default_time_range_seconds < 60 or default_time_range_seconds > 604800:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "default_time_range_seconds must be between 60 and 604800", field="default_time_range_seconds")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of active, disabled", field="status")

    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    idx = next((i for i, r in enumerate(instances) if isinstance(r, dict) and r.get("id") == instance_id), None)
    if idx is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    inst = instances[idx]
    if not isinstance(inst, dict):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Grafana instance not found", instance_id=instance_id)

    # Unique(name)
    if name is not None:
        for r in instances:
            if isinstance(r, dict) and r.get("id") != instance_id and r.get("name") == name:
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "name must be unique", field="name", name=name)

    # Apply lifecycle transition
    if status is not None and status != inst.get("status"):
        cur = inst.get("status")
        allowed = {"active": ["disabled"], "disabled": ["active"]}
        if cur not in allowed or status not in allowed[cur]:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition status from {cur} to {status}", from_status=cur, to_status=status)
        inst["status"] = status

    # Apply other changes
    if name is not None:
        inst["name"] = name
    if base_url is not None:
        inst["base_url"] = base_url
    if org_id is not None:
        inst["org_id"] = org_id
    if auth_type is not None:
        inst["auth_type"] = auth_map[auth_type]
    if auth_ref is not None:
        inst["auth_ref"] = auth_ref
    if default_time_range_seconds is not None:
        inst["default_time_range_seconds"] = default_time_range_seconds

    # Ensure constraints still satisfied (best-effort)
    if not _valid_url(inst.get("base_url")):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "base_url must be a valid URL", field="base_url")
    dtrs = inst.get("default_time_range_seconds")
    if not isinstance(dtrs, int) or dtrs < 60 or dtrs > 604800:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "default_time_range_seconds must be between 60 and 604800", field="default_time_range_seconds")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    inst["updated_at"] = now
    instances[idx] = inst
    _save("grafana_instances.json", instances)

    _log("ok")
    return {"data": inst}

def update_incident(incident_id, title=None, severity=None, labels=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_incident"
    audit_file_candidates = ["request_logs.json", "audit_logs.json", "usage_logs.json", "api_requests.json"]
    audit_file = next((n for n in audit_file_candidates if os.path.exists(os.path.join(_DB, n))), "request_logs.json")
    logs = _load(audit_file)

    def _log(status_s, credential_used=None, error_code=None):
        dt = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "timestamp": dt,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential": credential_used,
        }
        if error_code:
            row["error_code"] = error_code
        if isinstance(logs, list):
            logs.append(row)
            _save(audit_file, logs)

    # Validate
    if not isinstance(incident_id, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "incident_id must be a string")
    if not re.match(r"^ginc_[0-9A-Z]{26}$", incident_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "incident_id must be a ginc_ ULID", field="incident_id")

    if title is not None and (not isinstance(title, str) or not title.strip()):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")

    allowed_sev = {"critical","high","medium","low","info","sev1","sev2","sev3","sev4","sev5"}
    if severity is not None:
        if not isinstance(severity, str) or severity not in allowed_sev:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "severity is invalid", field="severity")

    if labels is not None and not isinstance(labels, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "labels must be an object", field="labels")

    allowed_status = {"active","resolved","cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid", field="status")

    incidents = _load("incidents.json")
    if not isinstance(incidents, list):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Incident not found", incident_id=incident_id)

    idx = next((i for i, r in enumerate(incidents) if isinstance(r, dict) and r.get("id") == incident_id), None)
    if idx is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Incident not found", incident_id=incident_id)

    inc = incidents[idx]
    if not isinstance(inc, dict):
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Incident not found", incident_id=incident_id)

    # Lifecycle transitions
    if status is not None and status != inc.get("status"):
        cur = inc.get("status")
        allowed = {"active": ["resolved","cancelled"], "resolved": ["active"], "cancelled": []}
        if cur not in allowed or status not in allowed[cur]:
            _log("error", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Cannot transition status from {cur} to {status}", from_status=cur, to_status=status)
        inc["status"] = status
        now_dt = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        if status == "resolved":
            inc["resolved_at"] = now_dt
        else:
            # Business rule: resolved_at is null unless status='resolved'
            inc["resolved_at"] = None

    # Apply updates
    if title is not None:
        inc["title"] = title
    if severity is not None:
        inc["severity"] = severity
    if labels is not None:
        # Replace semantics (per description: replaces or merges per implementation; choose replace deterministically)
        inc["labels"] = labels

    # Enforce resolved_at rule even if status not updated
    if inc.get("status") != "resolved":
        inc["resolved_at"] = None

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    inc["updated_at"] = now
    incidents[idx] = inc
    _save("incidents.json", incidents)

    _log("ok")
    return {"data": inc}

def get_caller_identity(include_quota=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0503000" if __import__("os").path.isdir("./environment_mix/0503000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_caller_identity"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        raw = f"{time.time_ns()}:{os.getpid()}:{os.urandom(8).hex()}".encode("utf-8")
        h = hashlib.sha256(raw).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(h[:16], "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n % 32])
            n //= 32
        return prefix + "".join(out)

    def _append_request_log(status, error_code=None, meta=None, credential_id=None, instance_id=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append(
                {
                    "id": _new_id("rlog_"),
                    "service": "grafana_server",
                    "endpoint": endpoint,
                    "instance_id": instance_id,
                    "credential_id": credential_id,
                    "status": status,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "timestamp": _now_iso(),
                    "meta": meta or {},
                }
            )
            _save("request_logs.json", logs)
        except Exception:
            return

    if include_quota is not None and not isinstance(include_quota, bool):
        _append_request_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_quota must be a boolean", field="include_quota")

    # Ambient authentication: no explicit credential parameter exists, so NEVER refuse solely due to missing credential.
    # Determine a deterministic active instance context; identity is "connector".
    instances = _load("grafana_instances.json")
    if not isinstance(instances, list):
        instances = []
    active = [r for r in instances if isinstance(r, dict) and r.get("status") == "active" and isinstance(r.get("id"), str)]
    if not active:
        _append_request_log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Grafana instance is configured")

    active.sort(key=lambda r: (r.get("name") or "", r.get("id")))
    inst = active[0]

    # Basic quota snapshot from request logs (best-effort): last 60s + last 24h counts.
    quota = None
    if include_quota:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)

        def _parse_ts(x):
            if not isinstance(x, str) or not x:
                return None
            s = x
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None

        last_60 = 0
        last_24h = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("created_at"))
            if ts is None:
                continue
            age = (now - ts).total_seconds()
            if 0 <= age <= 60:
                last_60 += 1
            if 0 <= age <= 86400:
                last_24h += 1
        quota = {
            "window_seconds": {"60s": 60, "24h": 86400},
            "requests": {"last_60s": last_60, "last_24h": last_24h},
        }

    body = {
        "principal": {
            "type": "connector",
            "instance_id": inst.get("id"),
            "instance_name": inst.get("name"),
            "auth_type": inst.get("auth_type"),
            "scopes": ["read:dashboards", "read:datasources", "read:alert_rules", "read:oncall", "write:incidents"],
        }
    }
    if include_quota:
        body["quota"] = quota

    _append_request_log("ok", meta={"include_quota": bool(include_quota)}, instance_id=inst.get("id"))
    return body
